files.research/company_profile/acceptance_poli:
"""Small, program-owned acceptance rules for research-only company profiles.

The policy deliberately reuses the semantic model's existing subject and evidence
fields.  It is not a confidence service or a persisted authorization layer.
"""

from __future__ import annotations

import re
from collections.abc import Mapping
from enum import Enum
from typing import Any

from .contracts import DispositionStatus
from .core_assessment_projection import business_description_is_unclear
from .models import (
    Activity,
    BusinessEvent,
    BusinessOverview,
    BusinessRegime,
    IndustryPackageAssignment,
    Measurement,
    MetricType,
    Relationship,
    Segment,
    SemanticRecord,
    SubjectBasis,
    SubjectScope,
)

_SELF_ACTORS = frozenset({"公司", "本公司", "本集团", "集团", "上市公司"})
_NARROWER_SCOPES = frozenset({"issuer", "named_subsidiary", "business_segment"})
_DEFAULT_GROUP_BASES = frozenset({None, "", "unclear", "report_default_group_scope"})
_SUBJECT_ASSIGNMENT_FAILURE = re.compile(r"无法归属|不可区分")
_SUBJECT_SCOPE_CONFLICT = re.compile(
    r"(?:主体|口径|归属).{0,12}(?:冲突|conflict)"
    r"|(?:冲突|conflict).{0,12}(?:主体|口径|归属)",
    re.IGNORECASE,
)
_PARENT_OR_SEGMENT_SCOPE = re.compile(r"母公司|本公司单体|业务分部")
_GROUP_INCLUSIVE_SUBSIDIARY = re.compile(
    r"(?:本公司|本集团|公司)及(?:其)?(?:所属|全资|控股)?子公司"
)
_NAMED_SUBSIDIARY_PREFIX = re.compile(
    r"^(?:全资|控股|所属)?子公司[\u4e00-\u9fffA-Za-z0-9（）()]{1,20}公司"
)
_NAMED_SUBSIDIARY_FACT = re.compile(
    r"(?<![及和与])(?:全资|控股|所属)?子公司"
    r"[\u4e00-\u9fffA-Za-z0-9（）()]{1,20}公司"
    r"(?:的)?"
    r"(?:营业收入|营业成本|营业利润|营收|收入|成本|毛利|净利润|利润总额|产能|产量|销量)"
)

CORE_CHAPTERS = (
    "extract_business_overview",
    "extract_segment_financials",
    "extract_operating_quantities",
    "extract_material_inputs",
    "extract_counterparties_and_concentration",
    "extract_business_regime",
)

_GROUP_BASES = {
    SubjectBasis.DIRECT_SOURCE_WORDING,
    SubjectBasis.REPORT_DEFAULT_GROUP_SCOPE,
    SubjectBasis.NUMERIC_RECONCILIATION_TO_CONSOLIDATED_STATEMENT,
}

# The values are intentionally closed.  ``display`` is source-native research
# display; the other flags unlock only genuinely group-comparable uses.
_SENSITIVE_TYPES = (Measurement, Relationship)


def usage_policy(record: SemanticRecord) -> dict[str, bool | str]:
    """Return the closed downstream-use decision for one accepted record."""

    if any(
        "official_income_unit_conflict:unclear" in item for item in record.uncertainty
    ):
        return {
            "display": True,
            "consolidated_aggregation": False,
            "ranking": False,
            "cross_company_comparison": False,
            "restriction_reason": "unclear_official_income_unit",
        }
    subject = record.subject_scope
    basis = record.subject_basis
    is_group = subject == SubjectScope.CONSOLIDATED_GROUP and basis in _GROUP_BASES
    if isinstance(
        record,
        (
            Activity,
            BusinessOverview,
            BusinessEvent,
            BusinessRegime,
            IndustryPackageAssignment,
        ),
    ):
        return {
            "display": True,
            "consolidated_aggregation": False,
            "ranking": False,
            "cross_company_comparison": False,
            "restriction_reason": (
                "unclear_official_business_description"
                if business_description_is_unclear(record)
                else "non_numeric_research_fact"
            ),
        }
    if isinstance(record, Segment):
        return {
            "display": True,
            "consolidated_aggregation": False,
            "ranking": False,
            "cross_company_comparison": False,
            "restriction_reason": "segment_identity_is_not_group_total",
        }
    if isinstance(record, _SENSITIVE_TYPES) and is_group:
        return {
            "display": True,
            "consolidated_aggregation": True,
            "ranking": True,
            "cross_company_comparison": True,
            "restriction_reason": "",
        }
    if isinstance(record, _SENSITIVE_TYPES):
        return {
            "display": True,
            "consolidated_aggregation": False,
            "ranking": False,
            "cross_company_comparison": False,
            "restriction_reason": (
                "unclear_subject_scope_restricted_from_consolidated_use"
                if subject == SubjectScope.UNCLEAR
                else "subject_scope_not_group_comparable"
            ),
        }
    return {
        "display": True,
        "consolidated_aggregation": False,
        "ranking": False,
        "cross_company_comparison": False,
        "restriction_reason": "subject_scope_not_group_comparable",
    }


def derive_confidence(
    record: SemanticRecord,
    *,
    disposition: DispositionStatus | str = DispositionStatus.ACCEPTED_FOR_REVIEW,
    contradiction: bool = False,
) -> str:
    """Derive a discrete confidence without weights or model-supplied scores."""

    status = disposition.value if isinstance(disposition, Enum) else str(disposition)
    if status != DispositionStatus.ACCEPTED_FOR_REVIEW.value:
        return "rejected"
    if contradiction or business_description_is_unclear(record):
        return "low"
    if not record.evidence:
        return "low"
    if record.subject_scope == SubjectScope.UNCLEAR:
        return "medium"
    if record.subject_basis in _GROUP_BASES or record.subject_basis in {
        SubjectBasis.DIRECT_GRAMMATICAL_ACTOR,
        SubjectBasis.EXPLICIT_ECONOMIC_RELATIONSHIP,
    }:
        return "high"
    if record.uncertainty:
        return "medium"
    return "medium"


def accepted_has_illegal_group_promotion(task_results: list[Any]) -> bool:
    """Detect a runtime record that claims group scope without affirmative basis."""

    for result in task_results:
        accepted_ids = {
            item.target_id
            for item in result.dispositions
            if item.status == DispositionStatus.ACCEPTED_FOR_REVIEW
        }
        for record in result.records:
            if (
                record.record_id in accepted_ids
                and record.subject_scope == SubjectScope.CONSOLIDATED_GROUP
                and not _has_affirmative_group_evidence(record)
            ):
                return True
    return False


def apply_report_default_group_scope(candidate: dict[str, Any]) -> dict[str, Any]:
    """Apply the report-level group convention to an otherwise unqualified draft."""

    scope = _scope_value(candidate.get("subject_scope"))
    basis = _scope_value(candidate.get("subject_basis"))
    if scope in _NARROWER_SCOPES:
        return candidate
    if (
        _object_type_value(candidate.get("object_type")) == "Segment"
        or candidate.get("row_class") == "consolidation_adjustment"
    ):
        return candidate
    if scope == "consolidated_group" and basis not in _DEFAULT_GROUP_BASES:
        return candidate
    if not report_default_group_is_legal(candidate):
        return _clear_default_group_subject(candidate)
    if scope in (None, "", "unclear"):
        candidate["subject_scope"] = "consolidated_group"
        candidate["subject_basis"] = "report_default_group_scope"
    return candidate


def report_default_group_is_legal(
    payload: SemanticRecord | Mapping[str, Any],
) -> bool:
    """Return whether default-group tags are allowed for this candidate's local evidence."""

    data = _as_subject_payload(payload)
    if _draft_is_third_party_activity(data):
        return False
    text = _local_subject_evidence_text(payload)
    if _has_subject_scope_conflict(text):
        return False
    return not _has_explicit_narrower_local_scope(payload, text)


def default_group_subject_is_unsupported(record: SemanticRecord) -> bool:
    """Return True when a default-group tag is not supported by local evidence."""

    if record.subject_scope != SubjectScope.CONSOLIDATED_GROUP:
        return False
    if record.subject_basis != SubjectBasis.REPORT_DEFAULT_GROUP_SCOPE:
        return False
    return not report_default_group_is_legal(record)


def operating_revenue_share_is_unsupported(record: SemanticRecord) -> bool:
    """Return True when a revenue share is not the locked 利息净收入 / 营业收入 row."""

    if not isinstance(record, Measurement) or record.field_id != "operating_revenue":
        return False
    if record.metric_type != MetricType.DISCLOSED_SHARE:
        return False
    return not (
        record.measured_object == "利息净收入"
        and record.relationship_context == "营业收入"
        and record.source_native.unit == "%"
    )


def explicit_group_wording_subject_is_unsupported(record: SemanticRecord) -> bool:
    """Return True when 本集团 is stated but the subject is not the group."""

    if not isinstance(record, Measurement) or record.field_id != "operating_revenue":
        return False
    if "本集团" not in _local_subject_evidence_text(record):
        return False
    # A group can disclose a named investee's own financial information. Its
    # reporting voice does not change the explicitly labelled income subject.
    if (
        record.subject_scope
        in {SubjectScope.NAMED_SUBSIDIARY, SubjectScope.BUSINESS_SEGMENT}
        and record.subject_basis == SubjectBasis.DIRECT_SOURCE_WORDING
        and re.match(
            r"重要(?:非全资子公司|合营企业|联营企业)/本期营业收入",
            record.source_native.header or "",
        )
        and (record.source_native.qualifier or "").endswith(
            "：" + record.measured_object
        )
        and re.sub(r"\s+", "", record.measured_object)
        in re.sub(
            r"\s+", "", " ".join(str(e.anchor.model_dump()) for e in record.evidence)
        )
    ):
        return False
    return not (
        record.subject_scope == SubjectScope.CONSOLIDATED_GROUP
        and record.subject_basis == SubjectBasis.DIRECT_SOURCE_WORDING
    )


def activity_promotes_third_party_to_group(record: SemanticRecord) -> bool:
    """Return True when a non-issuer actor is treated as the listed-company group."""

    if not isinstance(record, Activity):
        return False
    if record.subject_scope != SubjectScope.CONSOLIDATED_GROUP:
        return False
    if record.subject_basis != SubjectBasis.REPORT_DEFAULT_GROUP_SCOPE:
        return False
    return any(
        actor not in _SELF_ACTORS
        for actor in (record.activity_actor.strip(), record.source_actor.strip())
        if actor
    )


def _scope_value(value: Any) -> str | None:
    if value is None:
        return None
    if isinstance(value, Enum):
        return value.value
    text = str(value).strip()
    return text or None


def _object_type_value(value: Any) -> str | None:
    return _scope_value(value)


def _as_subject_payload(
    payload: SemanticRecord | Mapping[str, Any],
) -> Mapping[str, Any]:
    if isinstance(payload, Mapping):
        return payload
    return {
        "object_type": payload.object_type,
        "activity_actor": getattr(payload, "activity_actor", None),
        "source_actor": getattr(payload, "source_actor", None),
    }


def _local_subject_evidence_text(
    payload: SemanticRecord | Mapping[str, Any],
) -> str:
    parts: list[str] = []
    if not isinstance(payload, Mapping):
        parts.extend(payload.uncertainty)
        parts.append(str(payload.source_native.name or ""))
        parts.append(str(payload.source_native.header or ""))
        parts.append(str(payload.subject_name or ""))
        if isinstance(payload, BusinessOverview):
            parts.append(payload.source_text)
        for evidence in payload.evidence:
            parts.append(evidence.section_title)
            anchor = evidence.anchor
            for key in (
                "bounded_quote",
                "row_label",
                "table_label",
                "column_header",
                "cell_locator",
            ):
                parts.append(str(getattr(anchor, key, "") or ""))
        return " ".join(part for part in parts if part)

    parts.extend(str(item) for item in payload.get("uncertainty") or () if item)
    source = payload.get("source_native") or {}
    if isinstance(source, Mapping):
        parts.append(str(source.get("name") or ""))
        parts.append(str(source.get("header") or ""))
    parts.append(str(payload.get("source_text") or ""))
    parts.append(str(payload.get("subject_name") or ""))
    for evidence in payload.get("evidence") or ():
        if not isinstance(evidence, Mapping):
            continue
        parts.append(str(evidence.get("section_title") or ""))
        anchor = evidence.get("anchor") or {}
        if isinstance(anchor, Mapping):
            for key in (
                "bounded_quote",
                "row_label",
                "table_label",
                "column_header",
                "cell_locator",
            ):
                parts.append(str(anchor.get(key) or ""))
    return " ".join(part for part in parts if part)


def _has_subject_scope_conflict(text: str) -> bool:
    return bool(
        _SUBJECT_ASSIGNMENT_FAILURE.search(text) or _SUBJECT_SCOPE_CONFLICT.search(text)
    )


def _has_explicit_narrower_local_scope(
    payload: SemanticRecord | Mapping[str, Any],
    text: str,
) -> bool:
    if _PARENT_OR_SEGMENT_SCOPE.search(text):
        return True
    remainder = _GROUP_INCLUSIVE_SUBSIDIARY.sub("", text)
    if _NAMED_SUBSIDIARY_FACT.search(remainder):
        return True
    return any(
        _NAMED_SUBSIDIARY_PREFIX.match(field.strip())
        for field in _local_subject_identity_fields(payload)
        if field and field.strip()
    )


def _local_subject_identity_fields(
    payload: SemanticRecord | Mapping[str, Any],
) -> list[str]:
    if not isinstance(payload, Mapping):
        fields = [
            str(payload.source_native.name or ""),
            str(payload.source_native.header or ""),
            str(payload.subject_name or ""),
        ]
        if isinstance(payload, BusinessOverview):
            fields.append(payload.source_text)
        for evidence in payload.evidence:
            fields.append(evidence.section_title)
            anchor = evidence.anchor
            for key in ("bounded_quote", "row_label", "table_label", "column_header"):
                fields.append(str(getattr(anchor, key, "") or ""))
        return fields

    source = payload.get("source_native") or {}
    fields = [
        str(source.get("name") or "") if isinstance(source, Mapping) else "",
        str(source.get("header") or "") if isinstance(source, Mapping) else "",
        str(payload.get("source_text") or ""),
        str(payload.get("subject_name") or ""),
    ]
    for evidence in payload.get("evidence") or ():
        if not isinstance(evidence, Mapping):
            continue
        fields.append(str(evidence.get("section_title") or ""))
        anchor = evidence.get("anchor") or {}
        if not isinstance(anchor, Mapping):
            continue
        for key in ("bounded_quote", "row_label", "table_label", "column_header"):
            fields.append(str(anchor.get(key) or ""))
    return fields


def _clear_default_group_subject(candidate: dict[str, Any]) -> dict[str, Any]:
    candidate["subject_scope"] = "unclear"
    if _scope_value(candidate.get("subject_basis")) == "report_default_group_scope":
        candidate.pop("subject_basis", None)
    return candidate


def _draft_is_third_party_activity(candidate: Mapping[str, Any]) -> bool:
    if _object_type_value(candidate.get("object_type")) != "Activity":
        return False
    actors = [
        str(candidate.get(key) or "").strip()
        for key in ("activity_actor", "source_actor")
    ]
    return any(actor and actor not in _SELF_ACTORS for actor in actors)


def _has_affirmative_group_evidence(record: SemanticRecord) -> bool:
    if record.subject_basis == SubjectBasis.REPORT_DEFAULT_GROUP_SCOPE:
        return report_default_group_is_legal(record)
    if (
        record.subject_basis
        == SubjectBasis.NUMERIC_RECONCILIATION_TO_CONSOLIDATED_STATEMENT
    ):
        return bool(record.uncertainty) and any(
            evidence.subject_evidence_pages for evidence in record.evidence
        )
    if record.subject_basis != SubjectBasis.DIRECT_SOURCE_WORDING:
        return False
    source_text = " ".join(
        str(getattr(evidence.anchor, "bounded_quote", "") or "")
        for evidence in record.evidence
    )
    source_text += " " + str(record.source_native.name or "")
    return bool(re.search(r"合并|本集团|集团", source_text))

files.research/company_profile/candidate_regis:
"""Full A-share company-profile candidate registry.

This module composes the existing official-asset universe, coverage rows, and
industry membership reads. It does not apply manufacturing first-wave filters,
fixed report years, or shadow/OOS exclusion lists.
"""

from __future__ import annotations

import inspect
from collections.abc import Callable, Mapping, Sequence
from typing import Any, Literal, Protocol

from pydantic import BaseModel, ConfigDict, Field, model_validator

from research.announcement_assets.models import timestamp_not_after_as_of

from .models import PRODUCTION_AUTHORIZATION

CANDIDATE_REGISTRY_SCHEMA_VERSION = "company_profile_a_share_candidate_registry.v1"
PRODUCTION_SCOPE_POLICY = "a_share_full_market.v1"

_ASSET_STATUSES = frozenset(
    {
        "available",
        "confirmed_missing",
        "incomplete",
        "retryable",
        "blocked",
        "not_covered",
    }
)


class _StrictModel(BaseModel):
    model_config = ConfigDict(extra="forbid", frozen=True, strict=True)


class ClassificationInfo(_StrictModel):
    sw_l1_code: str | None = None
    sw_l1_name: str | None = None
    sw_l2_code: str | None = None
    sw_l2_name: str | None = None
    sw_l3_code: str | None = None
    sw_l3_name: str | None = None
    official_industry_code: str | None = None
    taxonomy_system: str | None = None
    mapping_status: str | None = None


class LatestAnnualReport(_StrictModel):
    asset_id: str = Field(min_length=1)
    fiscal_year: int
    report_period: str = Field(min_length=1)
    content_hash: str | None = None
    availability: str = Field(min_length=1)
    decision_state: str = Field(min_length=1)
    published_at: str | None = None


class AShareProfileCandidate(_StrictModel):
    instrument_id: str = Field(min_length=1)
    exchange: str = Field(min_length=1)
    company_name: str
    listed_date: str | None = None
    universe_status: Literal["eligible", "indeterminate"]
    exclusion_reason: str | None = None
    classification_status: Literal["present", "missing"]
    classification: ClassificationInfo | None = None
    asset_status: Literal[
        "available",
        "confirmed_missing",
        "incomplete",
        "retryable",
        "blocked",
        "not_covered",
    ]
    asset_blocker: str | None = None
    latest_effective_annual_report: LatestAnnualReport | None = None

    @model_validator(mode="after")
    def _status_invariants(self) -> AShareProfileCandidate:
        if self.universe_status == "eligible" and self.exclusion_reason:
            raise ValueError("eligible candidates cannot carry an exclusion reason")
        if self.universe_status == "indeterminate" and not self.exclusion_reason:
            raise ValueError("indeterminate candidates require an exclusion reason")
        if self.classification_status == "missing" and self.classification is not None:
            raise ValueError("missing classification cannot carry classification fields")
        if self.classification_status == "present" and self.classification is None:
            raise ValueError("present classification requires classification fields")
        return self


class AShareCandidateRegistry(_StrictModel):
    schema_version: Literal["company_profile_a_share_candidate_registry.v1"] = (
        CANDIDATE_REGISTRY_SCHEMA_VERSION
    )
    production_authorization: Literal["not_authorized"] = PRODUCTION_AUTHORIZATION
    policy_version: Literal["a_share_full_market.v1"] = PRODUCTION_SCOPE_POLICY
    as_of: str = Field(min_length=1)
    universe_snapshot_id: str | None = None
    universe_policy_version: str | None = None
    universe_coverage_guarantee: Literal[
        "full_market", "complete_unpaired", "unknown"
    ] = "unknown"
    candidates: tuple[AShareProfileCandidate, ...]
    counts: dict[str, int]

    def candidate(self, instrument_id: str) -> AShareProfileCandidate:
        for item in self.candidates:
            if item.instrument_id == instrument_id:
                return item
        raise KeyError(instrument_id)


class UniverseSnapshotRepository(Protocol):
    def get_latest_full_market_universe_snapshot(self) -> Mapping[str, Any] | None: ...

    def get_latest_complete_universe_snapshot(self) -> Mapping[str, Any] | None: ...

    def list_asset_coverage(
        self, universe_snapshot_id: str
    ) -> Sequence[Mapping[str, Any]]: ...


IndustryLookup = Callable[[str, str], Mapping[str, Any] | None]
ReportLookup = Callable[..., Any]


def candidate_registry_schema_manifest() -> dict[str, Any]:
    schema = AShareCandidateRegistry.model_json_schema()
    return {
        "schema_version": CANDIDATE_REGISTRY_SCHEMA_VERSION,
        "title": schema.get("title", "AShareCandidateRegistry"),
        "properties": schema.get("properties", {}),
        "schema": schema,
    }


def build_a_share_candidate_registry(
    *,
    as_of: str,
    eligible_instruments: Sequence[Mapping[str, Any]],
    indeterminate: Sequence[Mapping[str, Any]] = (),
    asset_coverage: Mapping[str, Mapping[str, Any]] | None = None,
    industry_memberships: Mapping[str, Mapping[str, Any] | None] | None = None,
    effective_reports: Mapping[str, Any] | None = None,
    universe_snapshot_id: str | None = None,
    universe_policy_version: str | None = None,
    excluded_instrument_ids: frozenset[str] | None = None,
    allowed_industry_groups: frozenset[str] | None = None,
    universe_coverage_guarantee: Literal[
        "full_market", "complete_unpaired", "unknown"
    ] = "unknown",
) -> AShareCandidateRegistry:
    """Assemble the production denominator from already-loaded source rows.

    ``excluded_instrument_ids`` and ``allowed_industry_groups`` are accepted only
    so callers can prove they are ignored. They never shrink the candidate set.
    """

    del excluded_instrument_ids, allowed_industry_groups
    coverage = asset_coverage or {}
    memberships = industry_memberships or {}
    reports = effective_reports or {}
    candidates = [
        *_candidates_from_rows(
            eligible_instruments,
            universe_status="eligible",
            coverage=coverage,
            memberships=memberships,
            reports=reports,
            as_of=as_of,
        ),
        *_candidates_from_rows(
            indeterminate,
            universe_status="indeterminate",
            coverage=coverage,
            memberships=memberships,
            reports=reports,
            as_of=as_of,
        ),
    ]
    candidates.sort(key=lambda item: item.instrument_id)
    return AShareCandidateRegistry(
        as_of=as_of,
        universe_snapshot_id=universe_snapshot_id,
        universe_policy_version=universe_policy_version,
        universe_coverage_guarantee=universe_coverage_guarantee,
        candidates=tuple(candidates),
        counts=_counts(candidates),
    )


def load_a_share_candidate_registry(
    *,
    universe_repository: UniverseSnapshotRepository,
    industry_lookup: IndustryLookup,
    effective_report_lookup: ReportLookup,
    as_of: str,
    snapshot: Mapping[str, Any] | None = None,
    first_wave_universe: Callable[..., Any] | None = None,
    shadow_exclusions: Callable[..., Any] | None = None,
) -> AShareCandidateRegistry:
    """Load a registry from existing universe/coverage/industry stores."""

    del first_wave_universe, shadow_exclusions
    loaded, coverage_guarantee = _resolve_universe_snapshot(
        universe_repository,
        as_of=as_of,
        snapshot=snapshot,
    )

    snapshot_id = str(loaded.get("snapshot_id") or "").strip() or None
    coverage_rows = (
        universe_repository.list_asset_coverage(snapshot_id) if snapshot_id else ()
    )
    coverage = {
        _instrument_id(row): row
        for row in coverage_rows
        if _instrument_id(row)
    }
    eligible = _snapshot_rows(loaded, "instruments", "instrument_rows")
    indeterminate = _snapshot_rows(loaded, "indeterminate", "indeterminate_rows")
    instrument_ids = [
        _instrument_id(row)
        for row in (*eligible, *indeterminate)
        if _instrument_id(row)
    ]
    memberships = {
        instrument_id: industry_lookup(instrument_id, as_of)
        for instrument_id in instrument_ids
    }
    reports = {
        instrument_id: _invoke_report_lookup(
            effective_report_lookup, instrument_id, as_of
        )
        for instrument_id in instrument_ids
    }
    return build_a_share_candidate_registry(
        as_of=as_of,
        eligible_instruments=eligible,
        indeterminate=indeterminate,
        asset_coverage=coverage,
        industry_memberships=memberships,
        effective_reports=reports,
        universe_snapshot_id=snapshot_id,
        universe_policy_version=str(loaded.get("policy_version") or "") or None,
        universe_coverage_guarantee=coverage_guarantee,
    )


def announcement_access_report_lookup(access: Any) -> ReportLookup:
    """Adapt AnnouncementAssetAccess.get_effective_asset to the registry lookup."""

    def lookup(instrument_id: str, as_of: str) -> Any:
        return access.get_effective_asset(
            instrument_id,
            knowledge_cutoff=_knowledge_cutoff(as_of),
        )

    return lookup


def load_official_task_candidate_registry(
    *,
    as_of: str,
    storage: Any,
    shared_asset_access: Any,
) -> AShareCandidateRegistry:
    """Load the official A-share denominator for the published task owner."""

    if shared_asset_access is None:
        raise ValueError("official live run requires announcement asset access")
    repository = getattr(shared_asset_access, "repository", None)
    if repository is None:
        raise ValueError("official live run requires a universe repository")
    return load_a_share_candidate_registry(
        universe_repository=repository,
        industry_lookup=_storage_industry_lookup(storage),
        effective_report_lookup=announcement_access_report_lookup(shared_asset_access),
        as_of=as_of,
    )


def _storage_industry_lookup(storage: Any) -> IndustryLookup:
    def lookup(instrument_id: str, as_of: str) -> Mapping[str, Any] | None:
        as_of_getter = getattr(storage, "get_industry_membership_as_of", None)
        if callable(as_of_getter):
            row = as_of_getter(instrument_id, as_of)
            if isinstance(row, Mapping):
                return _with_taxonomy_l1_name(storage, row)
            blocker = getattr(
                storage,
                "industry_classification_history_blocks_current_membership",
                None,
            )
            if callable(blocker) and blocker(instrument_id, as_of):
                return None
        getter = getattr(storage, "get_industry_membership", None)
        if callable(getter):
            row = getter(instrument_id)
            if isinstance(row, Mapping):
                return row
        return None

    return lookup


def _candidates_from_rows(
    rows: Sequence[Mapping[str, Any]],
    *,
    universe_status: Literal["eligible", "indeterminate"],
    coverage: Mapping[str, Mapping[str, Any]],
    memberships: Mapping[str, Mapping[str, Any] | None],
    reports: Mapping[str, Any],
    as_of: str,
) -> list[AShareProfileCandidate]:
    candidates: list[AShareProfileCandidate] = []
    seen: set[str] = set()
    for row in rows:
        instrument_id = _instrument_id(row)
        if not instrument_id or instrument_id in seen:
            continue
        seen.add(instrument_id)
        classification = _classification(memberships.get(instrument_id))
        coverage_row = coverage.get(instrument_id)
        report = _latest_report(reports.get(instrument_id), as_of=as_of)
        candidates.append(
            AShareProfileCandidate(
                instrument_id=instrument_id,
                exchange=_exchange(row),
                company_name=_company_name(row),
                listed_date=_optional_text(row.get("listed_date")),
                universe_status=universe_status,
                exclusion_reason=(
                    _optional_text(row.get("reason"))
                    if universe_status == "indeterminate"
                    else None
                ),
                classification_status="present" if classification else "missing",
                classification=classification,
                asset_status=_asset_status(coverage_row),
                asset_blocker=_asset_blocker(coverage_row),
                latest_effective_annual_report=report,
            )
        )
    return candidates


def _counts(candidates: Sequence[AShareProfileCandidate]) -> dict[str, int]:
    eligible = sum(item.universe_status == "eligible" for item in candidates)
    indeterminate = sum(item.universe_status == "indeterminate" for item in candidates)
    classification_missing = sum(
        item.classification_status == "missing" for item in candidates
    )
    asset_available = sum(item.asset_status == "available" for item in candidates)
    return {
        "total": len(candidates),
        "eligible": eligible,
        "indeterminate": indeterminate,
        "classification_missing": classification_missing,
        "asset_available": asset_available,
        "asset_not_available": len(candidates) - asset_available,
    }


def _snapshot_rows(
    snapshot: Mapping[str, Any], *keys: str
) -> tuple[Mapping[str, Any], ...]:
    for key in keys:
        raw = snapshot.get(key)
        if raw is None:
            continue
        if isinstance(raw, Mapping):
            items = raw.get("items", raw.get("rows", ()))
        else:
            items = raw
        if isinstance(items, Sequence) and not isinstance(items, (str, bytes)):
            return tuple(item for item in items if isinstance(item, Mapping))
    return ()


def _classification(row: Mapping[str, Any] | None) -> ClassificationInfo | None:
    if not row:
        return None
    info = ClassificationInfo(
        sw_l1_code=_optional_text(row.get("sw_l1_code")),
        sw_l1_name=_optional_text(row.get("sw_l1_name")),
        sw_l2_code=_optional_text(row.get("sw_l2_code")),
        sw_l2_name=_optional_text(row.get("sw_l2_name")),
        sw_l3_code=_optional_text(row.get("sw_l3_code")),
        sw_l3_name=_optional_text(row.get("sw_l3_name")),
        official_industry_code=_optional_text(
            row.get("official_industry_code") or row.get("industry_code")
        ),
        taxonomy_system=_optional_text(row.get("taxonomy_system")),
        mapping_status=_optional_text(row.get("mapping_status")),
    )
    if not any(
        (
            info.sw_l1_code,
            info.sw_l1_name,
            info.sw_l2_code,
            info.sw_l2_name,
            info.sw_l3_code,
            info.sw_l3_name,
            info.official_industry_code,
            info.taxonomy_system,
            info.mapping_status,
        )
    ):
        return None
    return info


def _latest_report(row: Any, *, as_of: str) -> LatestAnnualReport | None:
    data = _report_mapping(row)
    if data is None:
        return None
    if _report_visible_after(data, as_of):
        return None
    asset_id = _optional_text(data.get("asset_id"))
    report_period = _optional_text(data.get("report_period"))
    availability = _optional_text(
        data.get("availability") or data.get("asset_availability")
    )
    decision_state = _optional_text(
        data.get("decision_state")
        or data.get("effective_decision_state")
        or data.get("effective_state")
    )
    fiscal_year = data.get("fiscal_year")
    if not asset_id or not report_period or not availability or not decision_state:
        return None
    if isinstance(fiscal_year, bool) or not isinstance(fiscal_year, int):
        return None
    return LatestAnnualReport(
        asset_id=asset_id,
        fiscal_year=fiscal_year,
        report_period=report_period,
        content_hash=_optional_text(data.get("content_hash")),
        availability=availability,
        decision_state=decision_state,
        published_at=_optional_text(data.get("published_at")),
    )


def _report_mapping(row: Any) -> dict[str, Any] | None:
    if row is None:
        return None
    if isinstance(row, Mapping):
        return dict(row)
    return {
        "asset_id": getattr(row, "asset_id", None),
        "fiscal_year": getattr(row, "fiscal_year", None),
        "report_period": getattr(row, "report_period", None),
        "content_hash": getattr(row, "content_hash", None),
        "availability": _enum_value(getattr(row, "availability", None)),
        "asset_availability": _enum_value(getattr(row, "asset_availability", None)),
        "decision_state": _enum_value(getattr(row, "decision_state", None)),
        "effective_state": getattr(row, "effective_state", None),
        "effective_decision_state": getattr(row, "effective_decision_state", None),
        "published_at": getattr(row, "published_at", None),
        "version_available_at": getattr(row, "version_available_at", None),
        "activated_at": getattr(row, "activated_at", None),
    }


def _report_visible_after(row: Mapping[str, Any], as_of: str) -> bool:
    for key in ("published_at", "version_available_at", "activated_at"):
        value = row.get(key)
        if value and not _timestamp_not_after(str(value), as_of, missing_ok=True):
            return True
    return False


def _resolve_universe_snapshot(
    universe_repository: UniverseSnapshotRepository,
    *,
    as_of: str,
    snapshot: Mapping[str, Any] | None,
) -> tuple[Mapping[str, Any], Literal["full_market", "complete_unpaired", "unknown"]]:
    if snapshot is not None:
        _ensure_snapshot_as_of(snapshot, as_of)
        return snapshot, _caller_coverage_guarantee(snapshot)

    as_of_full = getattr(
        universe_repository, "get_full_market_universe_snapshot_as_of", None
    )
    if callable(as_of_full):
        loaded = as_of_full(as_of)
        if loaded is not None:
            _ensure_snapshot_as_of(loaded, as_of)
            return loaded, "full_market"

    latest_full = universe_repository.get_latest_full_market_universe_snapshot()
    if latest_full is not None and _snapshot_usable_as_of(latest_full, as_of):
        return latest_full, "full_market"

    as_of_complete = getattr(
        universe_repository, "get_complete_universe_snapshot_as_of", None
    )
    if callable(as_of_complete):
        loaded = as_of_complete(as_of)
        if loaded is not None:
            _ensure_snapshot_as_of(loaded, as_of)
            return loaded, "complete_unpaired"

    if latest_full is not None:
        raise ValueError(
            f"no universe snapshot is available as of {as_of}; "
            "refusing to label current data with a historical as_of"
        )

    latest_complete = universe_repository.get_latest_complete_universe_snapshot()
    if latest_complete is not None and _snapshot_usable_as_of(latest_complete, as_of):
        return latest_complete, "complete_unpaired"
    if latest_complete is not None:
        raise ValueError(
            f"no universe snapshot is available as of {as_of}; "
            "refusing to label current data with a historical as_of"
        )
    raise ValueError("universe snapshot is required for the A-share candidate registry")


def _caller_coverage_guarantee(
    snapshot: Mapping[str, Any],
) -> Literal["full_market", "complete_unpaired", "unknown"]:
    if snapshot.get("paired_census_snapshot_id"):
        return "full_market"
    return "unknown"


def _ensure_snapshot_as_of(snapshot: Mapping[str, Any], as_of: str) -> None:
    if not _snapshot_usable_as_of(snapshot, as_of):
        raise ValueError(
            f"no universe snapshot is available as of {as_of}; "
            "refusing to label current data with a historical as_of"
        )


def _snapshot_usable_as_of(snapshot: Mapping[str, Any], as_of: str) -> bool:
    snapshot_at = _optional_text(snapshot.get("snapshot_at"))
    if snapshot_at is None:
        return False
    return _timestamp_not_after(snapshot_at, as_of, missing_ok=False)


def _invoke_report_lookup(lookup: ReportLookup, instrument_id: str, as_of: str) -> Any:
    try:
        parameters = inspect.signature(lookup).parameters
    except (TypeError, ValueError):
        parameters = {}
    if "as_of" in parameters:
        return lookup(instrument_id, as_of=as_of)
    if any(
        item.kind in (inspect.Parameter.VAR_POSITIONAL, inspect.Parameter.VAR_KEYWORD)
        for item in parameters.values()
    ):
        return lookup(instrument_id, as_of)
    if len(parameters) >= 2:
        return lookup(instrument_id, as_of)
    return lookup(instrument_id)


def _knowledge_cutoff(as_of: str) -> str:
    text = str(as_of or "").strip()
    if len(text) == 10:
        return f"{text}T23:59:59.999999+08:00"
    return text


def _timestamp_not_after(value: str, as_of: str, *, missing_ok: bool) -> bool:
    text = str(value or "").strip()
    bound = str(as_of or "").strip()
    if not text:
        return missing_ok
    if not bound:
        raise ValueError("as_of is required")
    return timestamp_not_after_as_of(text, bound)


def _enum_value(value: Any) -> Any:
    if value is None:
        return None
    return getattr(value, "value", value)


def _asset_status(row: Mapping[str, Any] | None) -> str:
    if not row:
        return "not_covered"
    status = str(row.get("status") or "").strip()
    if status in _ASSET_STATUSES:
        return status
    return "not_covered"


def _asset_blocker(row: Mapping[str, Any] | None) -> str | None:
    if not row:
        return None
    evidence = row.get("evidence")
    if isinstance(evidence, Mapping):
        blocker = _optional_text(evidence.get("coverage_blocker") or evidence.get("blocker"))
        if blocker:
            return blocker
    return _optional_text(row.get("coverage_blocker") or row.get("blocker"))


def _instrument_id(row: Mapping[str, Any]) -> str:
    return str(row.get("instrument_id") or "").strip()


def _exchange(row: Mapping[str, Any]) -> str:
    return str(row.get("exchange") or "").strip() or "UNKNOWN"


def _company_name(row: Mapping[str, Any]) -> str:
    listing = row.get("listing_metadata")
    listing_name = ""
    if isinstance(listing, Mapping):
        listing_name = str(listing.get("security_name") or "").strip()
    return str(
        row.get("name")
        or row.get("security_name")
        or listing_name
        or _instrument_id(row)
    ).strip()


def _with_taxonomy_l1_name(
    storage: Any,
    row: Mapping[str, Any],
) -> Mapping[str, Any]:
    """Attach the L1 name from the stored taxonomy parent chain."""

    if _optional_text(row.get("sw_l1_name")):
        return row
    resolver = getattr(storage, "resolve_industry_taxonomy_l1_name", None)
    system = _optional_text(row.get("taxonomy_system"))
    code = _optional_text(row.get("official_industry_code"))
    if not callable(resolver) or not system or not code:
        return row
    name = _optional_text(
        resolver(
            taxonomy_system=system,
            taxonomy_version=row.get("taxonomy_version") or "",
            industry_code=code,
        )
    )
    if not name:
        return row
    projected = dict(row)
    projected["sw_l1_name"] = name
    return projected


def _optional_text(value: Any) -> str | None:
    text = str(value or "").strip()
    return text or None

files.research/company_profile/commodity_expos:
"""Derived commodity-exposure schema and catalog adaptation.

This is the unique owner for company_profile_commodity_exposure.v1. It does
not add Stage 5 extract objects or field_ids, and it does not copy quantities
from legacy Activity numeric fields. Empty, unread, and failed association
lists are coverage states, not a zero-exposure claim. Writer activation and
query surfaces stay out of this slice.
"""

from __future__ import annotations

import hashlib
import json
import re
from collections.abc import Sequence
from typing import Any, Literal

from pydantic import BaseModel, ConfigDict, Field, model_validator

from research.company_profile.models import (
    PRODUCTION_AUTHORIZATION,
    Activity,
    ActivityAction,
    AssertionClass,
    BusinessEvent,
    Evidence,
    Measurement,
    MetricType,
    PeriodType,
    Relationship,
    RelationshipType,
    ReportIdentity,
    SemanticRecord,
    SubjectBasis,
    SubjectScope,
)

COMMODITY_EXPOSURE_SCHEMA_VERSION = "company_profile_commodity_exposure.v1"
COMMODITY_EXPOSURE_POLICY_VERSION = "company_profile_commodity_exposure.v1"
COMMODITY_ROLE_RULE_VERSION = "company_profile_commodity_role.v1"
COMMODITY_EXPOSURE_WRITER = "company_profile_research_writer.v1"
COMMODITY_EXPOSURE_READ_OWNER = "company_profile_read_service.v1"
_FORBIDDEN_PROJECTION_FIELDS = frozenset(
    {
        "net_profit_direction",
        "net_exposure",
        "elasticity",
        "price_sensitivity",
    }
)


class _StrictModel(BaseModel):
    model_config = ConfigDict(extra="forbid", frozen=True, strict=True)


class MappingStatus:
    MAPPED = "mapped"
    PENDING = "pending"
    AMBIGUOUS = "ambiguous"


class CommodityRole:
    PRODUCT_SALES = "product_sales"
    RAW_MATERIAL_INPUT = "raw_material_input"
    ENERGY_CONSUMPTION = "energy_consumption"
    HEDGE_UNDERLYING = "hedge_underlying"
    UNKNOWN = "unknown"


_ENERGY_CONSUMPTION_VERBS = frozenset({"消耗", "耗用", "用电", "耗电"})
_ENERGY_CONSUMPTION_OBJECTS = frozenset({"电力", "蒸汽", "用电量", "电"})
_HEDGE_MARKERS = ("套保", "套期", "hedge")
_HEDGE_NEGATIONS = (
    "未开展",
    "未进行",
    "未从事",
    "未参与",
    "未做",
    "不开展",
    "不进行",
    "无套保",
    "无套期",
    "没有开展",
    "没有进行",
    "不存在套保",
    "不存在套期",
    "no hedge",
    "not hedge",
    "without hedge",
)
_CLAUSE_SPLIT = re.compile(r"[,，;；。.!！?？]+")
_ROLE_SOURCE_METRICS = frozenset({MetricType.SALES_VOLUME})
_ROLE_QUANTITY_METRICS: dict[str, frozenset[MetricType]] = {
    CommodityRole.PRODUCT_SALES: frozenset({MetricType.SALES_VOLUME}),
    CommodityRole.RAW_MATERIAL_INPUT: frozenset(),
    CommodityRole.ENERGY_CONSUMPTION: frozenset(),
    CommodityRole.HEDGE_UNDERLYING: frozenset(),
}


class MarketLinkStatus:
    NOT_LINKED = "not_linked"
    LINKED = "linked"
    AMBIGUOUS = "ambiguous"


class AssessmentStatus:
    NOT_ASSESSED = "not_assessed"
    ASSESSED = "assessed"
    EXTRACTION_FAILED = "extraction_failed"


def _reject_blank_ids(ids: Sequence[str], *, label: str) -> None:
    if any(not str(item).strip() for item in ids):
        raise ValueError(f"{label} cannot be blank")


def _accepted_index(
    records: Sequence[SemanticRecord],
) -> dict[str, SemanticRecord]:
    index: dict[str, SemanticRecord] = {}
    for record in records:
        key = str(record.record_id).strip()
        if not key:
            raise ValueError("accepted record_id cannot be blank")
        existing = index.get(key)
        if existing is not None and existing != record:
            raise ValueError("accepted records have conflicting record_id")
        index[key] = record
    return index


def _unique_evidence_index(
    items: Sequence[Evidence],
    *,
    label: str,
) -> dict[str, Evidence]:
    index: dict[str, Evidence] = {}
    for item in items:
        key = str(item.evidence_id).strip()
        if not key:
            raise ValueError(f"{label} cannot be blank")
        existing = index.get(key)
        if existing is not None and existing != item:
            raise ValueError(f"conflicting evidence for {key}")
        index[key] = item
    return index


def _validate_exposure_references(
    exposure: CommodityExposure,
    accepted_records: Sequence[SemanticRecord],
) -> None:
    index = _accepted_index(accepted_records)
    sources = []
    for record_id in exposure.source_record_ids:
        record = index.get(record_id)
        if record is None:
            raise ValueError(
                "source_record_ids must resolve to accepted new-model facts"
            )
        if record.report != exposure.report:
            raise ValueError("source_record_ids must belong to the same report")
        sources.append(record)
    measurements = []
    for record_id in exposure.measurement_record_ids:
        record = index.get(record_id)
        if record is None or not isinstance(record, Measurement):
            raise ValueError(
                "measurement_record_ids must resolve to same-report Measurement"
            )
        if record.report != exposure.report:
            raise ValueError("measurement_record_ids must belong to the same report")
        measurements.append(record)
    owned_evidence = _unique_evidence_index(
        tuple(item for record in (*sources, *measurements) for item in record.evidence),
        label="evidence_ids",
    )
    for evidence_id in exposure.evidence_ids:
        evidence = owned_evidence.get(evidence_id)
        if evidence is None:
            raise ValueError("evidence_ids must belong to the referenced source facts")
        if evidence.report != exposure.report:
            raise ValueError("evidence_ids must belong to the same report")


def _validate_assessment_references(
    assessment: CommodityExposureAssessment,
    checked_evidence: Sequence[Evidence],
) -> None:
    by_id = _unique_evidence_index(checked_evidence, label="checked_evidence_ids")
    if any(item.report != assessment.report for item in checked_evidence):
        raise ValueError("checked evidence must belong to the same report")
    for evidence_id in assessment.checked_evidence_ids:
        evidence = by_id.get(evidence_id)
        if evidence is None:
            raise ValueError(
                "checked_evidence_ids must resolve to this-report Evidence"
            )


class CommodityCatalogMapping(_StrictModel):
    source_native_name: str = Field(min_length=1)
    mapping_status: Literal["mapped", "pending", "ambiguous"]
    commodity_id: str | None = None
    product_ids: tuple[str, ...] = ()
    catalog_version: str = Field(min_length=1)
    mapping_version: str = Field(min_length=1)

    @model_validator(mode="after")
    def _mapping_identity(self) -> CommodityCatalogMapping:
        if self.mapping_status == MappingStatus.MAPPED:
            if not self.commodity_id:
                raise ValueError("mapped commodity requires commodity_id")
        elif self.commodity_id is not None:
            raise ValueError("unmapped commodity cannot carry commodity_id")
        return self


class CommodityExposure(_StrictModel):
    schema_version: Literal["company_profile_commodity_exposure.v1"] = (
        COMMODITY_EXPOSURE_SCHEMA_VERSION
    )
    exposure_id: str = Field(min_length=1)
    production_authorization: Literal["not_authorized"] = PRODUCTION_AUTHORIZATION
    report: ReportIdentity
    reported_period: str = Field(min_length=1)
    period_type: PeriodType
    knowledge_time: str | None = None
    subject_scope: SubjectScope
    subject_basis: SubjectBasis | None = None
    business_object: str | None = None
    source_record_ids: tuple[str, ...] = Field(min_length=1)
    evidence_ids: tuple[str, ...] = Field(min_length=1)
    measurement_record_ids: tuple[str, ...] = ()
    source_native_name: str = Field(min_length=1)
    commodity_id: str | None = None
    mapping_status: Literal["mapped", "pending", "ambiguous"]
    role: Literal[
        "product_sales",
        "raw_material_input",
        "energy_consumption",
        "hedge_underlying",
        "unknown",
    ]
    assertion_class: Literal["deterministic_derivation"] = (
        AssertionClass.DETERMINISTIC_DERIVATION.value
    )
    mapping_version: str = Field(min_length=1)
    policy_version: Literal["company_profile_commodity_exposure.v1"] = (
        COMMODITY_EXPOSURE_POLICY_VERSION
    )
    market_series_id: str | None = None
    market_link_status: Literal["not_linked", "linked", "ambiguous"] = (
        MarketLinkStatus.NOT_LINKED
    )
    uncertainty: tuple[str, ...] = ()

    @model_validator(mode="after")
    def _contract_invariants(self) -> CommodityExposure:
        _reject_blank_ids(self.source_record_ids, label="source_record_ids")
        _reject_blank_ids(self.evidence_ids, label="evidence_ids")
        _reject_blank_ids(self.measurement_record_ids, label="measurement_record_ids")
        if self.mapping_status == MappingStatus.MAPPED:
            if not self.commodity_id:
                raise ValueError("mapped commodity requires commodity_id")
        elif self.commodity_id is not None:
            raise ValueError("unmapped commodity cannot carry commodity_id")
        if self.market_link_status == MarketLinkStatus.LINKED:
            if not self.market_series_id:
                raise ValueError("linked market series requires market_series_id")
        elif self.market_series_id is not None:
            raise ValueError("unlinked market series cannot carry market_series_id")
        if self.role == CommodityRole.HEDGE_UNDERLYING and not self.source_record_ids:
            raise ValueError("hedge_underlying requires accepted hedge source records")
        return self


class CommodityExposureAssessment(_StrictModel):
    schema_version: Literal["company_profile_commodity_exposure.v1"] = (
        COMMODITY_EXPOSURE_SCHEMA_VERSION
    )
    production_authorization: Literal["not_authorized"] = PRODUCTION_AUTHORIZATION
    report: ReportIdentity
    assessment_status: Literal["not_assessed", "assessed", "extraction_failed"]
    checked_evidence_ids: tuple[str, ...] = ()
    exposures: tuple[CommodityExposure, ...] = ()

    @model_validator(mode="after")
    def _status_matches_association_scope(self) -> CommodityExposureAssessment:
        _reject_blank_ids(self.checked_evidence_ids, label="checked_evidence_ids")
        if any(item.report != self.report for item in self.exposures):
            raise ValueError("assessment exposures must belong to the same report")
        if self.assessment_status == AssessmentStatus.NOT_ASSESSED:
            if self.exposures:
                raise ValueError("not_assessed assessment cannot carry exposures")
            if self.checked_evidence_ids:
                raise ValueError(
                    "not_assessed assessment cannot carry checked evidence"
                )
        elif self.assessment_status == AssessmentStatus.EXTRACTION_FAILED:
            if self.exposures:
                raise ValueError("extraction_failed assessment cannot carry exposures")
        elif not self.exposures and not self.checked_evidence_ids:
            raise ValueError(
                "assessed empty exposure list requires checked evidence scope"
            )
        return self


def bind_commodity_exposure(
    exposure: CommodityExposure,
    *,
    accepted_records: Sequence[SemanticRecord],
) -> CommodityExposure:
    """Resolve published IDs against accepted facts without storing the facts."""

    _validate_exposure_references(exposure, accepted_records)
    return exposure


