files.research/company_profile/live_plan.py:
"""Pre-live run plan for company-profile source review.

This is the unique owner for recording budget, executable sampling, recall
denominator and first-expansion numeric thresholds before a live task. It does
not execute the task, call LLM, or fit thresholds from observed results.
"""

from __future__ import annotations

from collections.abc import Mapping, Sequence
from typing import Any, Literal

from pydantic import BaseModel, ConfigDict, Field, model_validator

from research.company_profile.candidate_registry import PRODUCTION_SCOPE_POLICY
from research.company_profile.models import PRODUCTION_AUTHORIZATION

# A priori operator cost caps. Copied from operations/execution so this owner
# does not import the task-service graph before a live run.
DEFAULT_LIVE_MAX_COMPANIES = 2
DEFAULT_LIVE_TOKEN_BUDGET = 50_000
DEFAULT_LIVE_MAX_ELAPSED_SECONDS = 300.0

LIVE_PLAN_SCHEMA_VERSION = "company_profile_live_plan.v1"
LIVE_PLAN_STATUS = "recorded_before_live"
_FORBIDDEN_RECALL_SOURCES = (
    "model_listed_fields",
    "evidence_id_existence",
    "gold24_equality",
)
_EXCHANGES = ("SSE", "SZSE", "BSE")
_DISCLOSURE_FORMS = ("manufacturing", "service", "finance", "other")
_STRATUM_PRIORITY = tuple(
    (exchange, form) for form in _DISCLOSURE_FORMS for exchange in _EXCHANGES
)
_FINANCE_L1 = frozenset({"银行", "非银金融"})
_SERVICE_L1 = frozenset(
    {
        "交通运输",
        "房地产",
        "商贸零售",
        "社会服务",
        "计算机",
        "传媒",
        "通信",
        "综合",
        "美容护理",
        "建筑装饰",
        "公用事业",
        "环保",
    }
)
_MANUFACTURING_L1 = frozenset(
    {
        "农林牧渔",
        "基础化工",
        "钢铁",
        "有色金属",
        "电子",
        "家用电器",
        "食品饮料",
        "纺织服饰",
        "轻工制造",
        "医药生物",
        "建筑材料",
        "电力设备",
        "机械设备",
        "国防军工",
        "煤炭",
        "石油石化",
        "汽车",
    }
)


class _StrictModel(BaseModel):
    model_config = ConfigDict(extra="forbid", frozen=True, strict=True)


def _exchange_of(candidate: Any) -> str:
    if isinstance(candidate, Mapping):
        return str(candidate.get("exchange") or "")
    return str(getattr(candidate, "exchange", "") or "")


def _instrument_id_of(candidate: Any) -> str:
    if isinstance(candidate, Mapping):
        return str(candidate.get("instrument_id") or "")
    return str(getattr(candidate, "instrument_id", "") or "")


def _sw_l1_name_of(candidate: Any) -> str | None:
    if isinstance(candidate, Mapping):
        direct = candidate.get("sw_l1_name")
        if direct:
            return str(direct)
        classification = candidate.get("classification")
        if isinstance(classification, Mapping):
            name = classification.get("sw_l1_name")
            return str(name) if name else None
        return None
    classification = getattr(candidate, "classification", None)
    name = getattr(classification, "sw_l1_name", None)
    return str(name) if name else None


def _classification_status_of(candidate: Any) -> str | None:
    if isinstance(candidate, Mapping):
        status = candidate.get("classification_status")
        return str(status) if status is not None else None
    status = getattr(candidate, "classification_status", None)
    return str(status) if status is not None else None


def _asset_status_of(candidate: Any) -> str | None:
    if isinstance(candidate, Mapping):
        status = candidate.get("asset_status")
        return str(status) if status is not None else None
    status = getattr(candidate, "asset_status", None)
    return str(status) if status is not None else None


def _latest_effective_annual_report_of(candidate: Any) -> Any:
    if isinstance(candidate, Mapping):
        return candidate.get("latest_effective_annual_report")
    return getattr(candidate, "latest_effective_annual_report", None)


def _has_effective_annual_report(candidate: Any) -> bool:
    report = _latest_effective_annual_report_of(candidate)
    if report is None:
        return False
    if isinstance(report, Mapping):
        return bool(report.get("asset_id") or report.get("report_period"))
    return bool(getattr(report, "asset_id", None) or getattr(report, "report_period", None))


def assign_disclosure_form(candidate: Any) -> str:
    """Map a candidate onto a predeclared disclosure-form stratum.

    Form comes only from the closed Shenwan L1 table. Caller-supplied
    ``disclosure_form`` is ignored. Missing or unlisted classification is
    ``other``.
    """

    if _classification_status_of(candidate) == "missing":
        return "other"
    name = _sw_l1_name_of(candidate)
    if name in _FINANCE_L1:
        return "finance"
    if name in _SERVICE_L1:
        return "service"
    if name in _MANUFACTURING_L1:
        return "manufacturing"
    return "other"


class LiveRunBudget(_StrictModel):
    max_companies_this_round: int = Field(ge=1)
    min_companies_this_round: int = Field(ge=0)
    token_budget: int = Field(ge=0)
    max_elapsed_seconds: float = Field(gt=0)
    require_fifty_companies: Literal[False] = False

    @model_validator(mode="after")
    def _no_forced_fifty(self) -> LiveRunBudget:
        if self.min_companies_this_round >= 50:
            raise ValueError("live plan cannot require fifty companies per round")
        if self.min_companies_this_round > self.max_companies_this_round:
            raise ValueError("minimum company quota cannot exceed this-round budget")
        return self


class StratifiedSamplingRule(_StrictModel):
    method: Literal["predeclared_stratified_sample"]
    purpose: Literal["independent_source_review"]
    allocation: Literal["priority_round_robin_then_instrument_id"]
    selection_key: Literal["instrument_id_ascending"]
    missing_classification_stratum: Literal["other"]
    empty_stratum_policy: Literal["keep_in_universe_skip_draw"]
    exchange_strata: tuple[str, ...]
    disclosure_form_strata: tuple[str, ...]
    stratum_priority: tuple[tuple[str, str], ...]
    per_stratum_first_draw: Literal[1]
    max_sample_size: int = Field(ge=1)
    review_eligible_asset_status: Literal["available"]
    review_requires_latest_effective_annual_report: Literal[True]
    excludes_from_universe: Literal[False]
    used_to_fit_thresholds: Literal[False]

    @model_validator(mode="after")
    def _executable_and_registered(self) -> StratifiedSamplingRule:
        if self.exchange_strata != _EXCHANGES:
            raise ValueError("sampling exchange strata must be SSE, SZSE, BSE")
        if self.disclosure_form_strata != _DISCLOSURE_FORMS:
            raise ValueError(
                "sampling disclosure-form strata must be manufacturing, "
                "service, finance, other"
            )
        expected_priority = tuple(
            (exchange, form)
            for form in self.disclosure_form_strata
            for exchange in self.exchange_strata
        )
        if self.stratum_priority != expected_priority:
            raise ValueError(
                "stratum_priority must be form-then-exchange over declared strata"
            )
        if self.used_to_fit_thresholds:
            raise ValueError("sampling cannot be used to fit thresholds")
        if self.excludes_from_universe:
            raise ValueError("sampling cannot exclude names from the universe")
        if self.review_eligible_asset_status != "available":
            raise ValueError("review sample can only draw available official reports")
        if not self.review_requires_latest_effective_annual_report:
            raise ValueError("review sample requires a latest effective annual report")
        return self


class UniverseDenominator(_StrictModel):
    policy_version: Literal["a_share_full_market.v1"]
    exchanges: tuple[str, ...]
    as_of: Literal["declared_at_run_from_knowledge_cutoff"]
    includes_missing_assets: Literal[True]
    includes_missing_classification: Literal[True]

    @model_validator(mode="after")
    def _full_market(self) -> UniverseDenominator:
        if self.exchanges != _EXCHANGES:
            raise ValueError("universe exchanges must be SSE, SZSE, BSE")
        if not self.includes_missing_assets:
            raise ValueError("universe denominator must keep missing assets")
        if not self.includes_missing_classification:
            raise ValueError("universe denominator must keep missing classification")
        return self


class RecallDenominator(_StrictModel):
    definition: Literal[
        "independently_read_important_disclosures_from_sampled_official_reports"
    ]
    forbidden_sources: tuple[str, ...]

    @model_validator(mode="after")
    def _independent_source_only(self) -> RecallDenominator:
        if frozenset(self.forbidden_sources) != frozenset(_FORBIDDEN_RECALL_SOURCES):
            raise ValueError(
                "recall denominator must forbid model-listed fields, "
                "evidence-id existence and gold24 equality"
            )
        if len(self.forbidden_sources) != len(set(self.forbidden_sources)):
            raise ValueError("recall forbidden sources cannot be duplicated")
        return self


class ExpansionQualityThresholds(_StrictModel):
    numeric_thresholds_basis: Literal["operator_cost_constraint"]
    min_independently_reviewed_reports: int = Field(ge=1)
    min_occupied_strata_reviewed: int = Field(ge=1)
    min_source_recall_ratio: float = Field(ge=1.0, le=1.0)
    min_source_accuracy_ratio: float = Field(ge=1.0, le=1.0)
    max_critical_numeric_errors: int = Field(ge=0, le=0)
    max_tokens: int = Field(ge=0)
    max_elapsed_seconds: float = Field(gt=0)
    max_companies_this_expansion: int = Field(ge=1)
    scale_quality_claim_allowed: Literal[False]
    fitted_from_observed_results: Literal[False]
    fixture_guards_are_not_live_quality: Literal[True]
    gold24_equality_is_not_a_threshold: Literal[True]
    untriggered_negatives_are_not_passes: Literal[True]
    expansion_requires_independent_source_review: Literal[True]

    @model_validator(mode="after")
    def _a_priori_numeric_gates(self) -> ExpansionQualityThresholds:
        if self.fitted_from_observed_results:
            raise ValueError("live plan cannot fit thresholds from observed results")
        if self.scale_quality_claim_allowed:
            raise ValueError("pre-live plan cannot claim scale quality")
        if self.min_source_recall_ratio != 1.0:
            raise ValueError("first-expansion recall threshold must be complete")
        if self.min_source_accuracy_ratio != 1.0:
            raise ValueError("first-expansion accuracy threshold must be complete")
        if self.max_critical_numeric_errors != 0:
            raise ValueError("first-expansion critical numeric errors must be zero")
        return self


class CompanyProfileLivePlan(_StrictModel):
    schema_version: Literal["company_profile_live_plan.v1"] = LIVE_PLAN_SCHEMA_VERSION
    production_authorization: Literal["not_authorized"] = PRODUCTION_AUTHORIZATION
    plan_status: Literal["recorded_before_live"] = LIVE_PLAN_STATUS
    live_task_started: Literal[False] = False
    budget: LiveRunBudget
    sampling: StratifiedSamplingRule
    universe_denominator: UniverseDenominator
    recall_denominator: RecallDenominator
    expansion_thresholds: ExpansionQualityThresholds

    @model_validator(mode="after")
    def _plan_is_internally_consistent(self) -> CompanyProfileLivePlan:
        if self.sampling.max_sample_size != self.budget.max_companies_this_round:
            raise ValueError("sample size must equal this-round company budget")
        if self.sampling.exchange_strata != self.universe_denominator.exchanges:
            raise ValueError("sampling exchanges must match the universe denominator")
        thresholds = self.expansion_thresholds
        if (
            thresholds.min_independently_reviewed_reports
            != self.budget.max_companies_this_round
        ):
            raise ValueError("reviewed-report threshold must equal this-round budget")
        if thresholds.min_occupied_strata_reviewed != min(
            self.budget.max_companies_this_round, len(self.sampling.stratum_priority)
        ):
            raise ValueError("occupied-strata threshold must follow this-round budget")
        if thresholds.max_companies_this_expansion != self.budget.max_companies_this_round:
            raise ValueError("first-expansion company cap must equal this-round budget")
        if thresholds.max_tokens != self.budget.token_budget:
            raise ValueError("first-expansion token cap must equal the run budget")
        if thresholds.max_elapsed_seconds != self.budget.max_elapsed_seconds:
            raise ValueError("first-expansion time cap must equal the run budget")
        return self


def _sampling_rule(*, max_sample_size: int) -> StratifiedSamplingRule:
    return StratifiedSamplingRule(
        method="predeclared_stratified_sample",
        purpose="independent_source_review",
        allocation="priority_round_robin_then_instrument_id",
        selection_key="instrument_id_ascending",
        missing_classification_stratum="other",
        empty_stratum_policy="keep_in_universe_skip_draw",
        exchange_strata=_EXCHANGES,
        disclosure_form_strata=_DISCLOSURE_FORMS,
        stratum_priority=_STRATUM_PRIORITY,
        per_stratum_first_draw=1,
        max_sample_size=max_sample_size,
        review_eligible_asset_status="available",
        review_requires_latest_effective_annual_report=True,
        excludes_from_universe=False,
        used_to_fit_thresholds=False,
    )


def _universe_denominator() -> UniverseDenominator:
    return UniverseDenominator(
        policy_version=PRODUCTION_SCOPE_POLICY,
        exchanges=_EXCHANGES,
        as_of="declared_at_run_from_knowledge_cutoff",
        includes_missing_assets=True,
        includes_missing_classification=True,
    )


def _recall_denominator() -> RecallDenominator:
    return RecallDenominator(
        definition=(
            "independently_read_important_disclosures_from_sampled_official_reports"
        ),
        forbidden_sources=_FORBIDDEN_RECALL_SOURCES,
    )


def _expansion_thresholds(
    *,
    max_companies_this_round: int,
    token_budget: int,
    max_elapsed_seconds: float,
) -> ExpansionQualityThresholds:
    return ExpansionQualityThresholds(
        numeric_thresholds_basis="operator_cost_constraint",
        min_independently_reviewed_reports=max_companies_this_round,
        min_occupied_strata_reviewed=min(
            max_companies_this_round, len(_STRATUM_PRIORITY)
        ),
        min_source_recall_ratio=1.0,
        min_source_accuracy_ratio=1.0,
        max_critical_numeric_errors=0,
        max_tokens=token_budget,
        max_elapsed_seconds=max_elapsed_seconds,
        max_companies_this_expansion=max_companies_this_round,
        scale_quality_claim_allowed=False,
        fitted_from_observed_results=False,
        fixture_guards_are_not_live_quality=True,
        gold24_equality_is_not_a_threshold=True,
        untriggered_negatives_are_not_passes=True,
        expansion_requires_independent_source_review=True,
    )


def record_company_profile_live_plan(
    *,
    max_companies_this_round: int = DEFAULT_LIVE_MAX_COMPANIES,
    token_budget: int = DEFAULT_LIVE_TOKEN_BUDGET,
    max_elapsed_seconds: float = DEFAULT_LIVE_MAX_ELAPSED_SECONDS,
) -> CompanyProfileLivePlan:
    """Record the operator budget and review rules before any live observation."""

    return CompanyProfileLivePlan(
        budget=LiveRunBudget(
            max_companies_this_round=max_companies_this_round,
            min_companies_this_round=0,
            token_budget=token_budget,
            max_elapsed_seconds=max_elapsed_seconds,
        ),
        sampling=_sampling_rule(max_sample_size=max_companies_this_round),
        universe_denominator=_universe_denominator(),
        recall_denominator=_recall_denominator(),
        expansion_thresholds=_expansion_thresholds(
            max_companies_this_round=max_companies_this_round,
            token_budget=token_budget,
            max_elapsed_seconds=max_elapsed_seconds,
        ),
    )


def select_stratified_review_sample(
    candidates: Sequence[Any],
    *,
    rule: StratifiedSamplingRule,
) -> tuple[str, ...]:
    """Pick instrument IDs with the predeclared rule.

    Missing-asset names stay out of the review sample. Model output is ignored.
    """

    buckets: dict[tuple[str, str], list[str]] = {
        stratum: [] for stratum in rule.stratum_priority
    }
    for candidate in candidates:
        instrument_id = _instrument_id_of(candidate)
        exchange = _exchange_of(candidate)
        if not instrument_id or exchange not in rule.exchange_strata:
            continue
        if _asset_status_of(candidate) != rule.review_eligible_asset_status:
            continue
        if (
            rule.review_requires_latest_effective_annual_report
            and not _has_effective_annual_report(candidate)
        ):
            continue
        form = assign_disclosure_form(candidate)
        buckets[(exchange, form)].append(instrument_id)
    ordered = {
        stratum: sorted(set(members)) for stratum, members in buckets.items()
    }
    selected: list[str] = []
    cursors = dict.fromkeys(rule.stratum_priority, 0)
    progressed = True
    while len(selected) < rule.max_sample_size and progressed:
        progressed = False
        for stratum in rule.stratum_priority:
            if len(selected) >= rule.max_sample_size:
                break
            members = ordered[stratum]
            index = cursors[stratum]
            if index < len(members):
                selected.append(members[index])
                cursors[stratum] = index + 1
                progressed = True
    return tuple(selected)


def live_plan_schema_manifest() -> dict[str, Any]:
    """Register the pre-live plan schema without starting a live task."""

    plan = record_company_profile_live_plan()
    return {
        "schema_version": LIVE_PLAN_SCHEMA_VERSION,
        "plan_status": LIVE_PLAN_STATUS,
        "production_authorization": PRODUCTION_AUTHORIZATION,
        "live_task_started": False,
        "forbidden_recall_sources": _FORBIDDEN_RECALL_SOURCES,
        "registered_budget": plan.budget.model_dump(mode="json"),
        "registered_sampling": plan.sampling.model_dump(mode="json"),
        "registered_expansion_thresholds": plan.expansion_thresholds.model_dump(
            mode="json"
        ),
        "plan_schema": CompanyProfileLivePlan.model_json_schema(),
    }

files.research/company_profile/live_run.py:
"""Budget-limited live-run accounting for company-profile common-core.

This is the unique owner for company_profile_live_run.v1. The published task
service still executes the queue. This module records the universe denominator
and per-company outcomes. It does not call LLM, enable production, or rerun a
batch because one company is missing supplemental information.
"""

from __future__ import annotations

from collections.abc import Sequence
from pathlib import Path
from typing import Any, Literal

from pydantic import BaseModel, ConfigDict, Field, model_validator

from research.company_profile.candidate_registry import (
    PRODUCTION_SCOPE_POLICY,
    AShareCandidateRegistry,
    AShareProfileCandidate,
)
from research.company_profile.live_plan import (
    CompanyProfileLivePlan,
    StratifiedSamplingRule,
    assign_disclosure_form,
    record_company_profile_live_plan,
    select_stratified_review_sample,
)
from research.company_profile.models import PRODUCTION_AUTHORIZATION

LIVE_RUN_SCHEMA_VERSION = "company_profile_live_run.v1"
_SELECTED_OUTCOMES = frozenset({"completed", "failed"})
_INSTRUMENT_EXCHANGES = {
    ".SH": "SSE",
    ".SZ": "SZSE",
    ".BJ": "BSE",
}


class _StrictModel(BaseModel):
    model_config = ConfigDict(extra="forbid", frozen=True, strict=True)


class UniverseRunDenominator(_StrictModel):
    policy_version: Literal["a_share_full_market.v1"]
    as_of: str = Field(min_length=1)
    total: int = Field(ge=0)
    eligible: int = Field(ge=0)
    missing_asset: int = Field(ge=0)
    missing_classification: int = Field(ge=0)
    selected_for_run: int = Field(ge=0)
    completed: int = Field(ge=0)
    failed: int = Field(ge=0)
    includes_missing_assets: Literal[True]

    @model_validator(mode="after")
    def _counts_are_consistent(self) -> UniverseRunDenominator:
        if self.policy_version != PRODUCTION_SCOPE_POLICY:
            raise ValueError("live-run denominator must stay full-market")
        if not self.includes_missing_assets:
            raise ValueError("live-run denominator must keep missing assets")
        if self.completed + self.failed != self.selected_for_run:
            raise ValueError("completed and failed must cover the selected run set")
        if self.missing_asset > self.total or self.eligible > self.total:
            raise ValueError("denominator counts cannot exceed the universe")
        return self


class SelectedSampleStratum(_StrictModel):
    instrument_id: str = Field(min_length=1)
    exchange: str = Field(min_length=1)
    disclosure_form: str = Field(min_length=1)

    @model_validator(mode="after")
    def _stratum_follows_instrument(self) -> SelectedSampleStratum:
        expected = _exchange_from_instrument_id(self.instrument_id)
        if self.exchange != expected:
            raise ValueError("selected stratum exchange must follow the instrument id")
        return self


class FrozenOfficialReportReference(_StrictModel):
    instrument_id: str = Field(min_length=1)
    asset_id: str = Field(min_length=1)
    report_id: str = Field(min_length=1)
    report_period: str = Field(min_length=1)
    document_version: str = Field(min_length=1)

    @model_validator(mode="after")
    def _no_unknown_document_version(self) -> FrozenOfficialReportReference:
        if self.document_version.strip().lower() == "unknown":
            raise ValueError("first expansion cannot use unknown document_version")
        if not self.report_id.strip():
            raise ValueError("first expansion requires an official report_id")
        return self


class CompanyRunOutcome(_StrictModel):
    instrument_id: str = Field(min_length=1)
    outcome: Literal["completed", "failed"]
    supplement_incomplete: bool
    delivered: bool
    batch_rerun_triggered: Literal[False]

    @model_validator(mode="after")
    def _delivery_matches_outcome(self) -> CompanyRunOutcome:
        if self.outcome == "completed" and not self.delivered:
            raise ValueError("completed company must be delivered")
        if self.outcome == "failed" and self.delivered:
            raise ValueError("failed company cannot be marked delivered")
        if self.batch_rerun_triggered:
            raise ValueError("incomplete supplement cannot rerun the batch")
        return self


class CompanyProfileLiveRunReport(_StrictModel):
    schema_version: Literal["company_profile_live_run.v1"] = LIVE_RUN_SCHEMA_VERSION
    production_authorization: Literal["not_authorized"] = PRODUCTION_AUTHORIZATION
    knowledge_cutoff: str = Field(min_length=1)
    plan: CompanyProfileLivePlan
    selected_instrument_ids: tuple[str, ...]
    selected_strata: tuple[SelectedSampleStratum, ...] = ()
    universe: UniverseRunDenominator
    company_outcomes: tuple[CompanyRunOutcome, ...]
    whole_batch_rerun: Literal[False]
    scale_quality_claim_allowed: Literal[False]
    first_expansion_plan_id: str | None = None
    frozen_report_references: tuple[FrozenOfficialReportReference, ...] = ()

    @model_validator(mode="after")
    def _report_matches_plan_and_selection(self) -> CompanyProfileLiveRunReport:
        if self.whole_batch_rerun:
            raise ValueError("live run cannot rerun the whole batch")
        if self.scale_quality_claim_allowed:
            raise ValueError("live run cannot claim scale quality")
        if self.plan.live_task_started:
            raise ValueError("pre-live plan snapshot cannot start the task itself")
        if len(self.selected_instrument_ids) > self.plan.budget.max_companies_this_round:
            raise ValueError("selected run set cannot exceed the live-plan budget")
        if len(self.selected_instrument_ids) != self.universe.selected_for_run:
            raise ValueError("selected ids must match the denominator")
        if len(self.company_outcomes) != len(self.selected_instrument_ids):
            raise ValueError("outcomes are recorded only for the selected run set")
        outcome_ids = tuple(item.instrument_id for item in self.company_outcomes)
        if outcome_ids != self.selected_instrument_ids:
            raise ValueError("outcome order must follow the selected run set")
        if len(set(self.selected_instrument_ids)) != len(self.selected_instrument_ids):
            raise ValueError("selected run set cannot contain duplicate companies")
        if self.first_expansion_plan_id:
            if not self.frozen_report_references:
                raise ValueError("first-expansion live run must freeze report references")
            if tuple(item.instrument_id for item in self.frozen_report_references) != (
                self.selected_instrument_ids
            ):
                raise ValueError("frozen reports must follow the selected run set")
        elif self.frozen_report_references:
            raise ValueError("frozen report references require a first-expansion plan id")
        if not self.selected_strata:
            return self
        stratum_ids = tuple(item.instrument_id for item in self.selected_strata)
        if stratum_ids != self.selected_instrument_ids:
            raise ValueError("selected strata must follow the selected run set")
        sampling = self.plan.sampling
        for item in self.selected_strata:
            if item.exchange not in sampling.exchange_strata:
                raise ValueError("selected stratum exchange is outside the sampling plan")
            if item.disclosure_form not in sampling.disclosure_form_strata:
                raise ValueError("selected stratum form is outside the sampling plan")
        return self


def select_live_run_targets(
    registry: AShareCandidateRegistry,
    plan: CompanyProfileLivePlan,
    *,
    instrument_ids: Sequence[str] = (),
) -> tuple[str, ...]:
    """Choose budget-limited official-report names. Missing assets stay out."""

    if instrument_ids:
        by_id = {item.instrument_id: item for item in registry.candidates}
        selected: list[str] = []
        seen: set[str] = set()
        for instrument_id in instrument_ids:
            if instrument_id in seen:
                continue
            candidate = by_id.get(instrument_id)
            if candidate is None:
                continue
            if not _review_eligible(candidate, plan.sampling):
                continue
            selected.append(instrument_id)
            seen.add(instrument_id)
            if len(selected) >= plan.budget.max_companies_this_round:
                break
        return tuple(selected)
    return select_stratified_review_sample(registry.candidates, rule=plan.sampling)


def record_live_run_report(
    *,
    plan: CompanyProfileLivePlan,
    registry: AShareCandidateRegistry,
    selected_instrument_ids: Sequence[str],
    delivered_instrument_ids: Sequence[str],
    knowledge_cutoff: str,
    incomplete_supplement_ids: Sequence[str] = (),
    first_expansion_plan_id: str | None = None,
    frozen_report_references: Sequence[FrozenOfficialReportReference] = (),
) -> CompanyProfileLiveRunReport:
    """Record universe counts and selected outcomes after one bounded run."""

    selected = tuple(selected_instrument_ids)
    delivered = set(delivered_instrument_ids)
    incomplete = set(incomplete_supplement_ids)
    by_id = {item.instrument_id: item for item in registry.candidates}
    for instrument_id in selected:
        candidate = by_id.get(instrument_id)
        if candidate is None or not _review_eligible(candidate, plan.sampling):
            raise ValueError("live run cannot select a name without an official report")
    outcomes = tuple(
        CompanyRunOutcome(
            instrument_id=instrument_id,
            outcome="completed" if instrument_id in delivered else "failed",
            supplement_incomplete=instrument_id in incomplete,
            delivered=instrument_id in delivered,
            batch_rerun_triggered=False,
        )
        for instrument_id in selected
    )
    completed = sum(item.outcome == "completed" for item in outcomes)
    failed = sum(item.outcome == "failed" for item in outcomes)
    return CompanyProfileLiveRunReport(
        knowledge_cutoff=knowledge_cutoff,
        plan=plan,
        selected_instrument_ids=selected,
        selected_strata=tuple(
            SelectedSampleStratum(
                instrument_id=instrument_id,
                exchange=by_id[instrument_id].exchange,
                disclosure_form=assign_disclosure_form(by_id[instrument_id]),
            )
            for instrument_id in selected
        ),
        universe=UniverseRunDenominator(
            policy_version=PRODUCTION_SCOPE_POLICY,
            as_of=knowledge_cutoff,
            total=registry.counts["total"],
            eligible=registry.counts["eligible"],
            missing_asset=registry.counts["asset_not_available"],
            missing_classification=registry.counts["classification_missing"],
            selected_for_run=len(selected),
            completed=completed,
            failed=failed,
            includes_missing_assets=True,
        ),
        company_outcomes=outcomes,
        whole_batch_rerun=False,
        scale_quality_claim_allowed=False,
        first_expansion_plan_id=first_expansion_plan_id,
        frozen_report_references=tuple(frozen_report_references),
    )


def persist_live_run_report(
    report: CompanyProfileLiveRunReport,
    root: str | Path,
    *,
    destination: Path | None = None,
) -> Path:
    """Write company_profile_live_run.v1 next to the task control snapshot."""

    path = (
        Path(destination)
        if destination is not None
        else Path(root) / "reports" / f"{LIVE_RUN_SCHEMA_VERSION}.json"
    )
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_suffix(".tmp")
    tmp.write_text(report.model_dump_json(indent=2), encoding="utf-8")
    tmp.replace(path)
    return path


def load_live_run_report(root: str | Path) -> CompanyProfileLiveRunReport:
    """Load the persisted live-run report required by source review.

    Pre-strata ``company_profile_live_run.v1`` snapshots remain readable.
    Missing layer records stay empty so source review cannot assess occupied
    strata or meet expansion gates.
    """

    path = Path(root) / "reports" / f"{LIVE_RUN_SCHEMA_VERSION}.json"
    if not path.is_file():
        raise ValueError("source review requires a persisted live-run report")
    return CompanyProfileLiveRunReport.model_validate_json(
        path.read_text(encoding="utf-8")
    )


def live_run_schema_manifest() -> dict[str, Any]:
    """Register the live-run report schema without enabling production."""

    return {
        "schema_version": LIVE_RUN_SCHEMA_VERSION,
        "production_authorization": PRODUCTION_AUTHORIZATION,
        "whole_batch_rerun": False,
        "plan_schema_version": record_company_profile_live_plan().schema_version,
        "report_schema": CompanyProfileLiveRunReport.model_json_schema(),
    }


def _review_eligible(
    candidate: AShareProfileCandidate,
    rule: StratifiedSamplingRule,
) -> bool:
    return bool(select_stratified_review_sample((candidate,), rule=rule))


def _exchange_from_instrument_id(instrument_id: str) -> str:
    for suffix, exchange in _INSTRUMENT_EXCHANGES.items():
        if instrument_id.endswith(suffix):
            return exchange
    raise ValueError("selected instrument id must map to SSE, SZSE or BSE")

files.research/company_profile/m4_next_batch.p:
"""Frozen-plan consumption for the next M4 small batch.

The existing task owner calls this module. It does not add a published action
and it does not rewrite the completed first-expansion snapshots.
"""

from __future__ import annotations

import hashlib
import json
from collections.abc import Callable, Mapping, Sequence
from pathlib import Path
from typing import Any

from pydantic import BaseModel, ConfigDict, Field, ValidationError, model_validator

SHARED_TOKEN_BUDGET = 50_000
MAX_COMPANIES_THIS_ROUND = 2
_BATCH_DIRNAME = "m4_next_small_batch"
_EXCHANGE_ORDER = ("SSE", "SZSE", "BSE")
_DISCLOSURE_FORMS = ("service", "manufacturing")
HISTORICAL_COMPLETED_INSTRUMENTS = frozenset({"600004.SH", "600006.SH"})
_REFERENCE_FIELDS = (
    "asset_id",
    "report_id",
    "report_period",
    "document_version",
)


class _StrictModel(BaseModel):
    model_config = ConfigDict(extra="forbid")


class M4NextBatchReport(_StrictModel):
    instrument_id: str = Field(min_length=1)
    asset_id: str = Field(min_length=1)
    report_id: str = Field(min_length=1)
    report_period: str = Field(min_length=1)
    document_version: str = Field(min_length=1)
    disclosure_form: str = Field(min_length=1)


class M4NextBatchPlan(_StrictModel):
    plan_id: str = Field(min_length=1)
    knowledge_cutoff: str = Field(min_length=1)
    max_companies_this_round: int = MAX_COMPANIES_THIS_ROUND
    token_budget: int = SHARED_TOKEN_BUDGET
    reports: tuple[M4NextBatchReport, ...]

    @model_validator(mode="after")
    def _freeze_two_company_budget(self) -> M4NextBatchPlan:
        if self.max_companies_this_round != MAX_COMPANIES_THIS_ROUND:
            raise ValueError("m4 next batch is limited to two companies")
        if self.token_budget != SHARED_TOKEN_BUDGET:
            raise ValueError("m4 next batch shares one 50000 token budget")
        if len(self.reports) != MAX_COMPANIES_THIS_ROUND:
            raise ValueError("m4 next batch plan must name exactly two reports")
        forms = [report.disclosure_form for report in self.reports]
        if forms != list(_DISCLOSURE_FORMS):
            raise ValueError("m4 next batch plan must list service then manufacturing")
        return self

    def report_for(self, instrument_id: str) -> M4NextBatchReport | None:
        for report in self.reports:
            if report.instrument_id == instrument_id:
                return report
        return None


class M4NextBatchOutcome(_StrictModel):
    instrument_id: str = Field(min_length=1)
    status: str = Field(min_length=1)
    tokens_consumed: int = 0
    reused_scope: bool = False
    reason: str | None = None


class M4NextBatchObservation(_StrictModel):
    plan_id: str = Field(min_length=1)
    knowledge_cutoff: str = Field(min_length=1)
    token_budget: int = SHARED_TOKEN_BUDGET
    tokens_consumed: int = 0
    outcomes: tuple[M4NextBatchOutcome, ...] = ()

    def outcome_for(self, instrument_id: str) -> M4NextBatchOutcome | None:
        for outcome in self.outcomes:
            if outcome.instrument_id == instrument_id:
                return outcome
        return None


def batch_directory(root: str | Path, plan_id: str) -> Path:
    return Path(root) / "reports" / _BATCH_DIRNAME / plan_id


def m4_snapshot_directory(
    root: str | Path,
    plan_id: str,
    *,
    plan_directory: str | Path | None = None,
) -> Path:
    """Old rounds stay under the unique batch directory. A repair names its own."""

    if plan_directory is not None:
        return Path(plan_directory)
    return batch_directory(root, plan_id)


def require_explicit_m4_plan(
    plan_directory: str | Path,
) -> M4NextBatchPlan:
    """Load a caller-selected plan, or refuse before any run or review write."""

    path = Path(plan_directory) / "plan.json"
    if not path.is_file():
        raise ValueError("explicit m4 plan is missing")
    try:
        return M4NextBatchPlan.model_validate_json(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError, ValidationError) as exc:
        raise ValueError("explicit m4 plan is invalid") from exc


def load_m4_next_batch_plan(
    root: str | Path,
    *,
    plan_directory: str | Path | None = None,
) -> M4NextBatchPlan | None:
    """Load the single frozen plan for this round, if one has been written."""

    if plan_directory is not None:
        path = Path(plan_directory) / "plan.json"
        if not path.is_file():
            return None
        return M4NextBatchPlan.model_validate_json(path.read_text(encoding="utf-8"))
    parent = Path(root) / "reports" / _BATCH_DIRNAME
    if not parent.is_dir():
        return None
    plans = sorted(parent.glob("*/plan.json"))
    if not plans:
        return None
    if len(plans) != 1:
        raise ValueError("m4 next batch requires exactly one frozen plan")
    return M4NextBatchPlan.model_validate_json(plans[0].read_text(encoding="utf-8"))


def save_m4_next_batch_plan(
    root: str | Path,
    plan: M4NextBatchPlan,
    *,
    plan_directory: str | Path | None = None,
) -> Path:
    """Write the plan once. A different sample or version is refused."""

    existing = load_m4_next_batch_plan(root, plan_directory=plan_directory)
    if existing is not None:
        if existing != plan:
            raise ValueError("frozen m4 next batch plan cannot be replaced")
        return m4_snapshot_directory(
            root, existing.plan_id, plan_directory=plan_directory
        ) / "plan.json"
    path = m4_snapshot_directory(
        root, plan.plan_id, plan_directory=plan_directory
    ) / "plan.json"
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(plan.model_dump_json(indent=2) + "\n", encoding="utf-8")
    return path


def load_m4_next_batch_observation(
    root: str | Path,
    plan: M4NextBatchPlan,
    *,
    plan_directory: str | Path | None = None,
) -> M4NextBatchObservation:
    path = m4_snapshot_directory(
        root, plan.plan_id, plan_directory=plan_directory
    ) / "observation.json"
    if not path.is_file():
        return M4NextBatchObservation(
            plan_id=plan.plan_id,
            knowledge_cutoff=plan.knowledge_cutoff,
            token_budget=plan.token_budget,
        )
    return M4NextBatchObservation.model_validate_json(path.read_text(encoding="utf-8"))


def save_m4_next_batch_observation(
    root: str | Path,
    observation: M4NextBatchObservation,
    *,
    plan_directory: str | Path | None = None,
) -> Path:
    path = m4_snapshot_directory(
        root, observation.plan_id, plan_directory=plan_directory
    ) / "observation.json"
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(observation.model_dump_json(indent=2), encoding="utf-8")
    return path


def load_m4_next_batch_observation_for_source_review(
    root: str | Path,
    *,
    plan_directory: str | Path | None = None,
) -> M4NextBatchObservation:
    """Source review reads the merged round, not one call's securities."""

    plan = load_m4_next_batch_plan(root, plan_directory=plan_directory)
    if plan is None:
        raise ValueError("m4 next-batch source review requires the frozen plan")
    observation = load_m4_next_batch_observation(
        root, plan, plan_directory=plan_directory
    )
    missing = [
        report.instrument_id
        for report in plan.reports
        if observation.outcome_for(report.instrument_id) is None
    ]
    if missing:
        raise ValueError(
            "m4 next-batch source review requires both company outcomes: "
            + ", ".join(missing)
        )
    return observation


def remaining_token_budget(observation: M4NextBatchObservation) -> int:
    return max(0, int(observation.token_budget) - int(observation.tokens_consumed))


def stable_plan_id(
    *,
    knowledge_cutoff: str,
    reports: Sequence[M4NextBatchReport],
) -> str:
    payload = {
        "knowledge_cutoff": knowledge_cutoff,
        "max_companies_this_round": MAX_COMPANIES_THIS_ROUND,
        "token_budget": SHARED_TOKEN_BUDGET,
        "reports": [report.model_dump() for report in reports],
    }
    encoded = json.dumps(payload, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(encoded.encode()).hexdigest()


def delivered_instrument_ids(
    output_root: str | Path,
    identity: Mapping[str, Any],
) -> set[str]:
    """Instruments that already have a runtime record for this processing identity."""

    namespace = Path(output_root) / "company_profile_common_core.v1"
    found: set[str] = set()
    if not namespace.is_dir():
        return found
    for path in namespace.glob("*.json"):
        try:
            payload = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            continue
        if not isinstance(payload, Mapping):
            continue
        execution = payload.get("execution") or {}
        input_identity = execution.get("input_identity") or {}
        processing = input_identity.get("processing_identity") or {}
        if dict(processing) != dict(identity):
            continue
        instrument_id = str((payload.get("report") or {}).get("instrument_id") or "")
        if instrument_id:
            found.add(instrument_id)
    return found


def select_m4_next_batch_reports(
    candidates: Sequence[Any],
    *,
    delivered_instrument_ids: set[str],
    readable,
    binding_for: Callable[[str], Mapping[str, Any] | None],
) -> tuple[M4NextBatchReport, M4NextBatchReport]:
    """Pick the first legal service company, then the first legal manufacturer."""

    excluded = set(delivered_instrument_ids) | HISTORICAL_COMPLETED_INSTRUMENTS
    chosen: list[M4NextBatchReport] = []
    for form in _DISCLOSURE_FORMS:
        report = _first_legal_report(
            candidates,
            disclosure_form=form,
            excluded=excluded,
            readable=readable,
            binding_for=binding_for,
        )
        if report is None:
            raise ValueError(f"m4 next batch has no legal {form} candidate")
        chosen.append(report)
        excluded.add(report.instrument_id)
    return tuple(chosen)


def build_m4_next_batch_plan(
    candidates: Sequence[Any],
    *,
    knowledge_cutoff: str,
    delivered_instrument_ids: set[str],
    readable,
    binding_for: Callable[[str], Mapping[str, Any] | None],
) -> M4NextBatchPlan:
    reports = select_m4_next_batch_reports(
        candidates,
        delivered_instrument_ids=delivered_instrument_ids,
        readable=readable,
        binding_for=binding_for,
    )
    return M4NextBatchPlan(
        plan_id=stable_plan_id(knowledge_cutoff=knowledge_cutoff, reports=reports),
        knowledge_cutoff=knowledge_cutoff,
        max_companies_this_round=MAX_COMPANIES_THIS_ROUND,
        token_budget=SHARED_TOKEN_BUDGET,
        reports=reports,
    )


def _first_legal_report(
    candidates: Sequence[Any],
    *,
    disclosure_form: str,
    excluded: set[str],
    readable,
    binding_for: Callable[[str], Mapping[str, Any] | None],
) -> M4NextBatchReport | None:
    from research.company_profile.live_plan import assign_disclosure_form

    grouped: dict[str, list[Any]] = {exchange: [] for exchange in _EXCHANGE_ORDER}
    for candidate in candidates:
        instrument_id = str(getattr(candidate, "instrument_id", "") or "")
        exchange = str(getattr(candidate, "exchange", "") or "")
        if not instrument_id or exchange not in grouped:
            continue
        if getattr(candidate, "universe_status", None) != "eligible":
            continue
        if instrument_id in excluded:
            continue
        if assign_disclosure_form(candidate) != disclosure_form:
            continue
        if not readable(candidate):
            continue
        grouped[exchange].append(candidate)
    for exchange in _EXCHANGE_ORDER:
        for candidate in sorted(grouped[exchange], key=lambda item: item.instrument_id):
            binding = binding_for(candidate.instrument_id)
            if binding is None:
                continue
            values = {
                field: str(binding.get(field) or "").strip() for field in _REFERENCE_FIELDS
            }
            if any(not values[field] for field in _REFERENCE_FIELDS):
                continue
            return M4NextBatchReport(
                instrument_id=candidate.instrument_id,
                disclosure_form=disclosure_form,
                **values,
            )
    return None


def tokens_consumed_by_call(*, tokens_used: int, reused_scope: bool) -> int:
    """Completed-scope reuse adds nothing. A failed call keeps its tokens."""

    if reused_scope:
        return 0
    return max(0, int(tokens_used))


def drift_reason(
    plan: M4NextBatchPlan,
    report: M4NextBatchReport,
    *,
    knowledge_cutoff: str,
    binding: Mapping[str, Any] | None,
) -> str | None:
    if knowledge_cutoff != plan.knowledge_cutoff:
        return "cutoff_drift"
    if binding is None:
        return "missing_official_binding"
    for field in _REFERENCE_FIELDS:
        if str(binding.get(field) or "").strip() != getattr(report, field):
            return f"{field}_drift"
    return None


def merge_outcome(
    observation: M4NextBatchObservation,
    outcome: M4NextBatchOutcome,
) -> M4NextBatchObservation:
    """Keep every other company and add this call's tokens to that company."""

    previous = observation.outcome_for(outcome.instrument_id)
    tokens = outcome.tokens_consumed
    if previous is not None:
        tokens = previous.tokens_consumed + outcome.tokens_consumed
    stored = outcome.model_copy(update={"tokens_consumed": tokens})
    kept = tuple(
        item for item in observation.outcomes if item.instrument_id != outcome.instrument_id
    )
    outcomes = kept + (stored,)
    return observation.model_copy(
        update={
            "outcomes": outcomes,
            "tokens_consumed": sum(item.tokens_consumed for item in outcomes),
        }
    )


def historical_snapshot_paths(root: str | Path) -> tuple[Path, ...]:
    reports = Path(root) / "reports"
    names = (
        "company_profile_first_expansion_mode.v1.json",
        "company_profile_first_expansion_plan.v1.json",
        "company_profile_operator_closure.v2.json",
        "company_profile_live_run.v1.json",
        "company_profile_source_review.v1.json",
    )
    return tuple(reports / name for name in names)


def snapshot_bytes(paths: Sequence[Path]) -> dict[str, bytes | None]:
    found: dict[str, bytes | None] = {}
    for path in paths:
        found[str(path)] = path.read_bytes() if path.is_file() else None
    return found

