"""Read published common-core profiles, templates, and structured exports.

This is the unique read owner for query/export. It does not enqueue work or
call Stage 5 writers. One completed company can be delivered immediately.
Commodity associations reuse the published assessment schema and keep DCF,
trading, and price-sensitivity consumers unauthorized.
"""

from __future__ import annotations

import csv
import fcntl
import json
import os
import re
import threading
from collections.abc import Iterator, Mapping, Sequence
from contextlib import contextmanager
from pathlib import Path
from typing import Any

from pydantic import TypeAdapter

from research.company_profile.commodity_exposure import (
    COMMODITY_EXPOSURE_READ_OWNER,
    AssessmentStatus,
    assess_commodity_exposures,
)
from research.company_profile.execution import default_processing_identity
from research.company_profile.models import (
    PRODUCTION_AUTHORIZATION,
    ReportIdentity,
    SemanticRecord,
)
from research.company_profile.runtime import (
    COMMON_CORE_STORAGE_NAMESPACE,
    COMMON_CORE_WRITER_NAME,
    CompanyProfileRuntimeRecord,
    json_compatible,
)
from research.company_profile.stage4_restricted_read import (
    FrozenChapterArtifacts,
    project_stage4_restricted_views,
)

PROFILE_SCHEMA_VERSION = "company_profile_common_core_profile.v1"
EXPORT_SCHEMA_VERSION = "company_profile_common_core_export.v1"
COMMODITY_CONSUMER_AUTHORIZATION = {
    "dcf": False,
    "trading": False,
    "price_sensitivity": False,
}
_RECORD_ADAPTER = TypeAdapter(SemanticRecord)
_SAFE_NAME = re.compile(r"[^A-Za-z0-9._-]+")


class CompanyProfileReadService:
    """Load published common-core records into a researcher-facing template."""

    read_owner = COMMODITY_EXPOSURE_READ_OWNER

    def __init__(
        self,
        output_root: str | Path,
        *,
        stage4_chapters: Sequence[FrozenChapterArtifacts] = (),
        stage4_root: str | Path | None = None,
        protected_export_roots: Sequence[str | Path] = (),
    ) -> None:
        self.output_root = Path(output_root)
        self.namespace_root = self.output_root / COMMON_CORE_STORAGE_NAMESPACE
        self.stage4_chapters = tuple(stage4_chapters)
        self.stage4_root = None if stage4_root is None else Path(stage4_root)
        self.protected_export_roots = tuple(
            Path(path) for path in protected_export_roots
        )

    def query(
        self,
        instrument_ids: Sequence[str] = (),
        *,
        processing_identity: Mapping[str, Any] | None = None,
        work_id: str | None = None,
    ) -> dict[str, Any]:
        requested = tuple(
            str(item).strip() for item in instrument_ids if str(item).strip()
        )
        profiles, missing = self._select_profiles(
            requested,
            processing_identity=processing_identity,
            work_id=work_id,
        )
        if profiles:
            state = "found"
        elif requested:
            state = "not_found"
        else:
            state = "idle"
        return {
            "action": "query",
            "state": state,
            "requested_instrument_ids": list(requested),
            "missing_instrument_ids": missing,
            "delivered": len(profiles),
            "profiles": profiles,
            "stage4_restricted_views": self._stage4_views(requested),
            "production_authorization": PRODUCTION_AUTHORIZATION,
            "storage_namespace": COMMON_CORE_STORAGE_NAMESPACE,
            "writer": COMMON_CORE_WRITER_NAME,
            "legacy_export_used": False,
        }

    def export(
        self,
        instrument_ids: Sequence[str] = (),
        export_directory: str | Path | None = None,
        processing_identity: Mapping[str, Any] | None = None,
        work_id: str | None = None,
    ) -> dict[str, Any]:
        if export_directory is None or not str(export_directory).strip():
            raise ValueError("export directory is required")
        queried = self.query(
            instrument_ids,
            processing_identity=processing_identity,
            work_id=work_id,
        )
        profiles = list(queried.get("profiles") or [])
        views = list(queried.get("stage4_restricted_views") or [])
        target = _resolve_export_directory(Path(export_directory))
        _reject_protected_export(target, self.protected_export_roots)
        profile_state = str(queried.get("state") or "idle")
        written: list[str] = []
        if profiles or views:
            with _exclusive_export(target):
                written.extend(_write_profile_export(target, profiles))
                written.extend(_write_stage4_export(target, views))
                manifest_path = target / "export_manifest.json"
                manifest = _export_manifest(
                    profiles=profiles,
                    views=views,
                    profile_state=profile_state,
                    files=[*written, str(manifest_path)],
                )
                manifest_path.write_text(
                    json.dumps(manifest, ensure_ascii=False, indent=2),
                    encoding="utf-8",
                )
                written.append(str(manifest_path))
        if profiles or views:
            state = "completed"
        elif profile_state == "not_found":
            state = "not_found"
        else:
            state = "idle"
        return {
            **queried,
            "action": "export",
            "state": state,
            "profile_state": profile_state,
            "restricted_delivered": len(views),
            "export_directory": str(target),
            "files": written,
        }

    def _stage4_views(self, instrument_ids: Sequence[str]) -> list[dict[str, Any]]:
        if not self.stage4_chapters or self.stage4_root is None:
            return []
        return project_stage4_restricted_views(
            instrument_ids,
            repo_root=self.stage4_root,
            chapters=self.stage4_chapters,
        )

    def _select_profiles(
        self,
        instrument_ids: Sequence[str],
        *,
        processing_identity: Mapping[str, Any] | None = None,
        work_id: str | None = None,
    ) -> tuple[list[dict[str, Any]], list[str]]:
        latest = self._latest_by_instrument(
            processing_identity=processing_identity,
            work_id=work_id,
        )
        if instrument_ids:
            selected = [
                latest[instrument_id]
                for instrument_id in instrument_ids
                if instrument_id in latest
            ]
            missing = [
                instrument_id
                for instrument_id in instrument_ids
                if instrument_id not in latest
            ]
        else:
            selected = [latest[key] for key in sorted(latest)]
            missing = []
        return [self.render_profile(item) for item in selected], missing

    def _latest_by_instrument(
        self,
        *,
        processing_identity: Mapping[str, Any] | None = None,
        work_id: str | None = None,
    ) -> dict[str, CompanyProfileRuntimeRecord]:
        latest: dict[str, CompanyProfileRuntimeRecord] = {}
        if not self.namespace_root.is_dir():
            return latest
        wanted_identity = (
            None if processing_identity is None else dict(processing_identity)
        )
        for path in self.namespace_root.glob("*.json"):
            if not path.is_file():
                continue
            try:
                record = CompanyProfileRuntimeRecord.model_validate_json(
                    path.read_text(encoding="utf-8")
                )
            except (OSError, ValueError):
                continue
            if work_id and record.work_id != work_id:
                continue
            if (
                wanted_identity is not None
                and _record_processing_identity(record) != wanted_identity
            ):
                continue
            instrument_id = record.report.instrument_id
            current = latest.get(instrument_id)
            if current is None or _record_sort_key(record) > _record_sort_key(current):
                latest[instrument_id] = record
        return latest

    def render_profile(self, record: CompanyProfileRuntimeRecord) -> dict[str, Any]:
        checkpoint = self._load_checkpoint(record.work_id)
        accepted = _accepted_facts(checkpoint)
        gaps = _gaps(record, checkpoint)
        assessment = record.assessment
        dimensions = [
            _dimension_view(assessment.principal_business),
            _dimension_view(assessment.products_services),
            _dimension_view(assessment.revenue_model),
        ]
        knowledge_time = next(
            (
                str(item.get("knowledge_time") or "")
                for item in accepted
                if item.get("knowledge_time")
            ),
            record.report.published_at,
        )
        return {
            "schema_version": PROFILE_SCHEMA_VERSION,
            "production_authorization": PRODUCTION_AUTHORIZATION,
            "storage_namespace": record.storage_namespace,
            "writer": record.writer,
            "work_id": record.work_id,
            "instrument_id": record.report.instrument_id,
            "report": json_compatible(record.report),
            "freshness": {
                "report_period": record.report.report_period,
                "published_at": record.report.published_at,
                "document_version": record.report.document_version,
                "knowledge_time": knowledge_time,
            },
            "core_complete": assessment.core_complete,
            "dimensions": dimensions,
            "accepted_facts": accepted,
            "gaps": gaps,
            "evidence_gap_codes": list(record.evidence_gap_codes),
            "commodity_exposure": _commodity_exposure_view(
                report=record.report,
                checkpoint=checkpoint,
                knowledge_time=knowledge_time,
            ),
        }

    def _load_checkpoint(self, work_id: str) -> dict[str, Any]:
        path = self.namespace_root / "checkpoints" / f"{work_id}.json"
        if not path.is_file():
            return {}
        try:
            payload = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            return {}
        return payload if isinstance(payload, dict) else {}


def _record_processing_identity(record: CompanyProfileRuntimeRecord) -> dict[str, Any]:
    identity = record.execution.input_identity
    if identity is None:
        return {}
    raw = identity.processing_identity
    return dict(raw) if raw else {}


def _record_sort_key(
    record: CompanyProfileRuntimeRecord,
) -> tuple[str, str, str, int, str]:
    current = default_processing_identity()
    return (
        str(record.report.report_period),
        str(record.report.published_at),
        str(record.report.document_version),
        1 if _record_processing_identity(record) == current else 0,
        str(record.work_id),
    )


def _dimension_view(item: Any) -> dict[str, Any]:
    return {
        "dimension_id": item.dimension_id,
        "answered": bool(item.answered),
        "excerpt": item.excerpt,
        "supporting_record_ids": list(item.supporting_record_ids),
        "evidence_ids": list(item.evidence_ids),
        "anchor": item.anchor,
        "missing_reason": item.missing_reason,
    }


def commodity_consumer_authorized(consumer: str) -> bool:
    """DCF, trading, and price-sensitivity stay unauthorized on this read path."""

    if consumer not in COMMODITY_CONSUMER_AUTHORIZATION:
        raise ValueError(f"unsupported commodity consumer: {consumer}")
    return COMMODITY_CONSUMER_AUTHORIZATION[consumer]


def _commodity_exposure_view(
    *,
    report: ReportIdentity,
    checkpoint: Mapping[str, Any],
    knowledge_time: str,
) -> dict[str, Any]:
    records = _accepted_semantic_records(checkpoint)
    evidence = tuple(
        item
        for record in records
        for item in record.evidence
        if item.report == report
    )
    status = (
        AssessmentStatus.ASSESSED
        if records
        else AssessmentStatus.NOT_ASSESSED
    )
    try:
        assessment = assess_commodity_exposures(
            report=report,
            assessment_status=status,
            accepted_records=records,
            checked_evidence=evidence,
        )
    except (TypeError, ValueError):
        assessment = assess_commodity_exposures(
            report=report,
            assessment_status=AssessmentStatus.EXTRACTION_FAILED,
            checked_evidence=evidence,
        )
    return {
        "assessment": json_compatible(assessment),
        "reported_period": report.report_period,
        "knowledge_time": knowledge_time,
        "consumer_authorization": dict(COMMODITY_CONSUMER_AUTHORIZATION),
    }


def _iter_accepted_raw(checkpoint: Mapping[str, Any]) -> list[Any]:
    items: list[Any] = list(checkpoint.get("accepted_records") or ())
    for scope in checkpoint.get("completed_scopes") or ():
        if not isinstance(scope, Mapping):
            continue
        result = scope.get("task_result") or {}
        if not isinstance(result, Mapping):
            continue
        accepted_ids = {
            str(item.get("target_id") or "")
            for item in result.get("dispositions") or ()
            if isinstance(item, Mapping)
            and item.get("status") == "accepted_for_review"
        }
        for raw in result.get("records") or ():
            if not isinstance(raw, Mapping):
                continue
            record_id = str(raw.get("record_id") or "")
            if record_id not in accepted_ids:
                continue
            items.append(raw)
    return items


def _accepted_semantic_records(
    checkpoint: Mapping[str, Any],
) -> tuple[SemanticRecord, ...]:
    records: list[SemanticRecord] = []
    seen: set[str] = set()
    for raw in _iter_accepted_raw(checkpoint):
        try:
            if isinstance(raw, Mapping):
                record = _RECORD_ADAPTER.validate_json(json.dumps(raw))
            else:
                record = _RECORD_ADAPTER.validate_python(raw)
        except (TypeError, ValueError):
            continue
        if not record.record_id or record.record_id in seen:
            continue
        seen.add(record.record_id)
        records.append(record)
    return tuple(records)


def _accepted_facts(checkpoint: Mapping[str, Any]) -> list[dict[str, Any]]:
    facts: list[dict[str, Any]] = []
    seen: set[str] = set()
    for raw in _iter_accepted_raw(checkpoint):
        _append_fact(facts, seen, raw)
    return facts


def _append_fact(
    facts: list[dict[str, Any]],
    seen: set[str],
    raw: Any,
) -> None:
    try:
        record = (
            raw
            if isinstance(raw, SemanticRecord)
            else _RECORD_ADAPTER.validate_python(raw)
        )
        payload = json_compatible(record)
    except (TypeError, ValueError):
        if not isinstance(raw, Mapping):
            return
        payload = dict(raw)
    record_id = str(payload.get("record_id") or "")
    if not record_id or record_id in seen:
        return
    evidence = []
    for item in payload.get("evidence") or ():
        if not isinstance(item, Mapping):
            continue
        anchor = item.get("anchor") or {}
        evidence.append(
            {
                "page": item.get("page"),
                "bounded_quote": (
                    anchor.get("bounded_quote")
                    if isinstance(anchor, Mapping)
                    else None
                ),
            }
        )
    seen.add(record_id)
    native = payload.get("source_native")
    native_map = native if isinstance(native, Mapping) else {}
    facts.append(
        {
            "record_id": record_id,
            "field_id": payload.get("field_id"),
            "object_type": payload.get("object_type"),
            "source_text": payload.get("source_text"),
            "source_actor": payload.get("source_actor"),
            "source_native_name": native_map.get("name"),
            "source_native_header": native_map.get("header"),
            "source_native_value": native_map.get("value"),
            "source_native_unit": native_map.get("unit"),
            "knowledge_time": payload.get("knowledge_time"),
            "reported_period": payload.get("reported_period"),
            **(
                {"uncertainty": payload["uncertainty"]}
                if payload.get("uncertainty")
                else {}
            ),
            "evidence": evidence,
        }
    )


def _gaps(
    record: CompanyProfileRuntimeRecord,
    checkpoint: Mapping[str, Any],
) -> list[dict[str, Any]]:
    evidence = checkpoint.get("evidence") or {}
    raw_gaps = evidence.get("gaps") if isinstance(evidence, Mapping) else None
    if raw_gaps:
        gaps = []
        for item in raw_gaps:
            if not isinstance(item, Mapping):
                continue
            gaps.append(
                {
                    "code": item.get("code"),
                    "chapter_task": item.get("chapter_task"),
                    "page": item.get("page"),
                    "message": item.get("message"),
                }
            )
        if gaps:
            return gaps
    return [{"code": code} for code in record.evidence_gap_codes]


def _profile_filename(profile: Mapping[str, Any]) -> str:
    instrument = _SAFE_NAME.sub("_", str(profile.get("instrument_id") or "unknown"))
    period = _SAFE_NAME.sub("_", str((profile.get("freshness") or {}).get("report_period") or "unknown"))
    return f"{instrument}_{period}.json"


def _write_profile_csv(path: Path, profiles: Sequence[Mapping[str, Any]]) -> None:
    fieldnames = [
        "instrument_id",
        "report_period",
        "published_at",
        "core_complete",
        "principal_business",
        "products_services",
        "revenue_model",
        "accepted_fact_count",
        "gap_count",
    ]
    with path.open("w", encoding="utf-8", newline="") as handle:
        writer = csv.DictWriter(handle, fieldnames=fieldnames)
        writer.writeheader()
        for profile in profiles:
            answered = {
                item["dimension_id"]: item["answered"]
                for item in profile.get("dimensions") or ()
            }
            freshness = profile.get("freshness") or {}
            writer.writerow(
                {
                    "instrument_id": profile.get("instrument_id"),
                    "report_period": freshness.get("report_period"),
                    "published_at": freshness.get("published_at"),
                    "core_complete": profile.get("core_complete"),
                    "principal_business": answered.get("principal_business"),
                    "products_services": answered.get("products_services"),
                    "revenue_model": answered.get("revenue_model"),
                    "accepted_fact_count": len(profile.get("accepted_facts") or ()),
                    "gap_count": len(profile.get("gaps") or ()),
                }
            )


def _resolve_export_directory(path: Path) -> Path:
    return path.expanduser().resolve()


def _reject_protected_export(target: Path, roots: Sequence[Path]) -> None:
    for root in roots:
        resolved_root = root.expanduser().resolve()
        if target == resolved_root or _is_relative_to(target, resolved_root):
            raise ValueError(
                f"export directory overlaps protected research inputs: {resolved_root}"
            )


def _is_relative_to(path: Path, root: Path) -> bool:
    try:
        path.relative_to(root)
    except ValueError:
        return False
    return True


_EXPORT_THREAD_GUARD = threading.Lock()
_EXPORT_THREAD_LOCKS: dict[str, threading.Lock] = {}


def _export_thread_lock(target: Path) -> threading.Lock:
    key = str(target)
    with _EXPORT_THREAD_GUARD:
        lock = _EXPORT_THREAD_LOCKS.get(key)
        if lock is None:
            lock = threading.Lock()
            _EXPORT_THREAD_LOCKS[key] = lock
        return lock


@contextmanager
def _exclusive_export(target: Path) -> Iterator[None]:
    """Hold the target directory exclusively before any export byte is written."""

    thread_lock = _export_thread_lock(target)
    if not thread_lock.acquire(blocking=False):
        raise ValueError(f"export directory is already in use: {target}")
    descriptor: int | None = None
    try:
        target.mkdir(parents=True, exist_ok=True)
        descriptor = os.open(target, os.O_RDONLY)
        try:
            fcntl.flock(descriptor, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except OSError as exc:
            raise ValueError(
                f"export directory is already in use: {target}"
            ) from exc
        _reject_existing_export(target)
        yield
    finally:
        if descriptor is not None:
            try:
                fcntl.flock(descriptor, fcntl.LOCK_UN)
            finally:
                os.close(descriptor)
        thread_lock.release()


def _reject_existing_export(target: Path) -> None:
    if target.is_symlink() or (target.exists() and not target.is_dir()):
        raise ValueError(f"export directory already contains output: {target}")
    if target.is_dir() and any(target.iterdir()):
        raise ValueError(f"export directory already contains output: {target}")


def _write_profile_export(
    target: Path,
    profiles: Sequence[Mapping[str, Any]],
) -> list[str]:
    written: list[str] = []
    if not profiles:
        return written
    for profile in profiles:
        path = target / _profile_filename(profile)
        path.write_text(
            json.dumps(profile, ensure_ascii=False, indent=2),
            encoding="utf-8",
        )
        written.append(str(path))
    csv_path = target / "profiles.csv"
    _write_profile_csv(csv_path, profiles)
    written.append(str(csv_path))
    return written


def _write_stage4_export(
    target: Path,
    views: Sequence[Mapping[str, Any]],
) -> list[str]:
    written: list[str] = []
    if not views:
        return written
    for view in views:
        path = target / _stage4_filename(view)
        path.write_text(
            json.dumps(view, ensure_ascii=False, indent=2),
            encoding="utf-8",
        )
        written.append(str(path))
    csv_path = target / "stage4_records.csv"
    _write_stage4_csv(csv_path, views)
    written.append(str(csv_path))
    return written


def _stage4_filename(view: Mapping[str, Any]) -> str:
    instrument = _SAFE_NAME.sub("_", str(view.get("instrument_id") or "unknown"))
    period = _SAFE_NAME.sub(
        "_",
        str((view.get("report") or {}).get("report_period") or "unknown"),
    )
    return f"{instrument}_{period}.stage4.json"


def _export_manifest(
    *,
    profiles: Sequence[Mapping[str, Any]],
    views: Sequence[Mapping[str, Any]],
    profile_state: str,
    files: Sequence[str],
) -> dict[str, Any]:
    return {
        "schema_version": EXPORT_SCHEMA_VERSION,
        "production_authorization": PRODUCTION_AUTHORIZATION,
        "scale_quality_claim_allowed": False,
        "storage_namespace": COMMON_CORE_STORAGE_NAMESPACE,
        "writer": COMMON_CORE_WRITER_NAME,
        "profile_state": profile_state,
        "delivered": len(profiles),
        "restricted_delivered": len(views),
        "profiles": [
            {
                "instrument_id": profile.get("instrument_id"),
                "report_period": (profile.get("freshness") or {}).get("report_period"),
                "file": _profile_filename(profile),
            }
            for profile in profiles
        ],
        "restricted_views": [
            {
                "instrument_id": view.get("instrument_id"),
                "report": view.get("report"),
                "core_profile_complete": view.get("core_profile_complete"),
                "gaps": view.get("gaps"),
                "production_authorization": view.get("production_authorization"),
                "scale_quality_claim_allowed": view.get("scale_quality_claim_allowed"),
                "chapters": [
                    {
                        "chapter_task": chapter.get("chapter_task"),
                        "plan_version": chapter.get("plan_version"),
                        "delivered": chapter.get("delivered"),
                        "reason": chapter.get("reason"),
                    }
                    for chapter in view.get("chapters") or ()
                ],
                "file": _stage4_filename(view),
            }
            for view in views
        ],
        "files": list(files),
        "legacy_export_used": False,
    }


_STAGE4_CSV_FIELDS = (
    "instrument_id",
    "report_id",
    "document_version",
    "content_hash",
    "report_period",
    "chapter_task",
    "plan_version",
    "delivered",
    "reason",
    "row_kind",
    "record_id",
    "page",
    "unit",
    "value",
    "bounded_quote",
    "outcome",
    "coverage_status",
    "payload_json",
)


def _write_stage4_csv(path: Path, views: Sequence[Mapping[str, Any]]) -> None:
    with path.open("w", encoding="utf-8", newline="") as handle:
        writer = csv.DictWriter(handle, fieldnames=_STAGE4_CSV_FIELDS)
        writer.writeheader()
        for view in views:
            report = view.get("report") or {}
            for chapter in view.get("chapters") or ():
                facts = list(chapter.get("facts") or ())
                coverage = list(chapter.get("coverage") or ())
                if not facts and not coverage:
                    writer.writerow(
                        _stage4_csv_row(
                            view,
                            report,
                            chapter,
                            row_kind="chapter",
                            payload={},
                        )
                    )
                for fact in facts:
                    writer.writerow(
                        _stage4_csv_row(
                            view,
                            report,
                            chapter,
                            row_kind="fact",
                            payload=fact,
                        )
                    )
                for item in coverage:
                    writer.writerow(
                        _stage4_csv_row(
                            view,
                            report,
                            chapter,
                            row_kind="coverage",
                            payload=item,
                        )
                    )


def _stage4_csv_row(
    view: Mapping[str, Any],
    report: Mapping[str, Any],
    chapter: Mapping[str, Any],
    *,
    row_kind: str,
    payload: Mapping[str, Any],
) -> dict[str, Any]:
    return {
        "instrument_id": view.get("instrument_id"),
        "report_id": report.get("report_id"),
        "document_version": report.get("document_version"),
        "content_hash": report.get("content_hash"),
        "report_period": report.get("report_period"),
        "chapter_task": chapter.get("chapter_task"),
        "plan_version": chapter.get("plan_version"),
        "delivered": chapter.get("delivered"),
        "reason": chapter.get("reason") or "",
        "row_kind": row_kind,
        "record_id": payload.get("record_id") or "",
        "page": payload.get("page") if payload else "",
        "unit": payload.get("unit") if payload else "",
        "value": payload.get("value") if payload else "",
        "bounded_quote": _bounded_quote(payload),
        "outcome": payload.get("outcome") if payload else "",
        "coverage_status": payload.get("coverage_status") if payload else "",
        "payload_json": (json.dumps(payload, ensure_ascii=False) if payload else ""),
    }


def _bounded_quote(payload: Mapping[str, Any]) -> str:
    if not payload:
        return ""
    direct = payload.get("bounded_quote")
    if direct:
        return str(direct)
    evidence = payload.get("evidence")
    if isinstance(evidence, list) and evidence and isinstance(evidence[0], Mapping):
        quote = evidence[0].get("bounded_quote")
        if quote:
            return str(quote)
        anchor = evidence[0].get("anchor")
        if isinstance(anchor, Mapping) and anchor.get("bounded_quote"):
            return str(anchor["bounded_quote"])
    return ""

files.research/company_profile/source_review.p:
"""Independent source review for a budget-limited company-profile live run.

This is the unique owner for company_profile_source_review.v1. It records
sampled core-skeleton, important-disclosure and commodity-role checks against
official reports. Structural existence is not semantic correctness. Unassessed
metrics stay unassessed and are not filled with zero. It does not call LLM or
enable production.
"""

from __future__ import annotations

from collections.abc import Sequence
from pathlib import Path
from typing import Annotated, Any, Literal

from pydantic import BaseModel, ConfigDict, Field, model_validator

from research.company_profile.live_run import CompanyProfileLiveRunReport
from research.company_profile.models import PRODUCTION_AUTHORIZATION

SOURCE_REVIEW_SCHEMA_VERSION = "company_profile_source_review.v1"
ReviewAspect = Literal["core_skeleton", "important_disclosure", "commodity_role"]
_REQUIRED_ASPECTS = frozenset(
    {"core_skeleton", "important_disclosure", "commodity_role"}
)


class _StrictModel(BaseModel):
    model_config = ConfigDict(extra="forbid", frozen=True, strict=True)


class UnassessedValue(_StrictModel):
    status: Literal["unassessed"] = "unassessed"
    value: None = None


class AssessedRatio(_StrictModel):
    status: Literal["assessed"] = "assessed"
    numerator: int = Field(ge=0)
    denominator: int = Field(ge=1)
    value: float = Field(ge=0, le=1)

    @model_validator(mode="after")
    def _ratio_matches_counts(self) -> AssessedRatio:
        expected = self.numerator / self.denominator
        if abs(self.value - expected) > 1e-12:
            raise ValueError("assessed ratio must equal numerator/denominator")
        return self


class AssessedCount(_StrictModel):
    status: Literal["assessed"] = "assessed"
    value: int = Field(ge=0)


class AssessedDuration(_StrictModel):
    status: Literal["assessed"] = "assessed"
    value: float = Field(ge=0)


QualityRatio = Annotated[
    AssessedRatio | UnassessedValue,
    Field(discriminator="status"),
]
QualityCount = Annotated[
    AssessedCount | UnassessedValue,
    Field(discriminator="status"),
]
QualityDuration = Annotated[
    AssessedDuration | UnassessedValue,
    Field(discriminator="status"),
]


class StructuralCheck(_StrictModel):
    instrument_id: str = Field(min_length=1)
    aspect: ReviewAspect
    kind: Literal["structural"]
    method: Literal["evidence_id_existence", "hash_presence", "page_reference"]
    passed: bool


class SemanticFinding(_StrictModel):
    instrument_id: str = Field(min_length=1)
    aspect: ReviewAspect
    kind: Literal["semantic"]
    source: Literal["independently_read_official_report"]
    disclosure_id: str = Field(min_length=1)
    disclosed_in_source: bool
    present_in_delivery: bool
    fact_accurate: bool | None
    critical_numeric_error: bool

    @model_validator(mode="after")
    def _semantic_finding_is_independent(self) -> SemanticFinding:
        if self.kind != "semantic":
            raise ValueError("semantic findings cannot be structural checks")
        if self.fact_accurate is True and not self.present_in_delivery:
            raise ValueError("absent delivery cannot be marked fact-accurate")
        if self.critical_numeric_error and self.fact_accurate is True:
            raise ValueError("a critical numeric error cannot be fact-accurate")
        return self


class FixtureGuardResult(_StrictModel):
    channel: Literal["fixture_guard"]
    name: str = Field(min_length=1)
    passed: bool


class FreshnessObservation(_StrictModel):
    instrument_id: str = Field(min_length=1)
    report_period: str = Field(min_length=1)
    published_at: str = Field(min_length=1)
    knowledge_cutoff: str = Field(min_length=1)
    available_at_cutoff: bool


class DeliveryCoverage(_StrictModel):
    universe_total: int = Field(ge=0)
    selected_for_run: int = Field(ge=0)
    completed: int = Field(ge=0)
    failed: int = Field(ge=0)
    missing_asset: int = Field(ge=0)
    semantic_status: Literal["not_a_source_metric"]


class SourceReviewWorkload(_StrictModel):
    tokens_used: QualityCount
    elapsed_seconds: QualityDuration
    human_review_minutes: QualityDuration


class CompanyProfileSourceReviewReport(_StrictModel):
    schema_version: Literal["company_profile_source_review.v1"] = (
        SOURCE_REVIEW_SCHEMA_VERSION
    )
    production_authorization: Literal["not_authorized"] = PRODUCTION_AUTHORIZATION
    live_run: CompanyProfileLiveRunReport
    structural_checks: tuple[StructuralCheck, ...]
    semantic_findings: tuple[SemanticFinding, ...]
    fixture_guards: tuple[FixtureGuardResult, ...]
    independently_reviewed_reports: int = Field(ge=0)
    occupied_strata_reviewed: QualityCount
    delivery_coverage: DeliveryCoverage
    source_recall: QualityRatio
    source_accuracy: QualityRatio
    critical_numeric_errors: QualityCount
    freshness: tuple[FreshnessObservation, ...]
    workload: SourceReviewWorkload
    expansion_gates_met: bool
    scale_quality_claim_allowed: Literal[False]
    zero_recurrence_claimed: Literal[False]

    @model_validator(mode="after")
    def _review_matches_live_sample_and_assessment(self) -> (
        CompanyProfileSourceReviewReport
    ):
        if self.scale_quality_claim_allowed:
            raise ValueError("source review cannot claim scale quality")
        if self.zero_recurrence_claimed:
            raise ValueError("source review cannot claim zero recurrence")
        selected = set(self.live_run.selected_instrument_ids)
        for item in (
            *self.structural_checks,
            *self.semantic_findings,
            *self.freshness,
        ):
            if item.instrument_id not in selected:
                raise ValueError("source review can only cover the live-run sample")
        finding_keys = [
            (item.instrument_id, item.aspect, item.disclosure_id)
            for item in self.semantic_findings
        ]
        if len(finding_keys) != len(set(finding_keys)):
            raise ValueError("semantic findings cannot repeat the same disclosure")
        derived = _derived_metrics(
            live_run=self.live_run,
            findings=self.semantic_findings,
            workload=self.workload,
        )
        if self.independently_reviewed_reports != derived["independently_reviewed_reports"]:
            raise ValueError("reviewed-report count must follow semantic findings")
        if self.occupied_strata_reviewed != derived["occupied_strata_reviewed"]:
            raise ValueError("occupied strata must follow the live-run sample layers")
        if self.source_recall != derived["source_recall"]:
            raise ValueError("source recall must follow semantic findings")
        if self.source_accuracy != derived["source_accuracy"]:
            raise ValueError("source accuracy must follow semantic findings")
        if self.critical_numeric_errors != derived["critical_numeric_errors"]:
            raise ValueError("critical numeric errors must follow semantic findings")
        if self.expansion_gates_met != derived["expansion_gates_met"]:
            raise ValueError("expansion gates must follow findings and the live plan")
        if not self.semantic_findings:
            if self.source_recall.status != "unassessed":
                raise ValueError("structure-only review cannot assess source recall")
            if self.source_accuracy.status != "unassessed":
                raise ValueError("structure-only review cannot assess source accuracy")
            if self.critical_numeric_errors.status != "unassessed":
                raise ValueError(
                    "structure-only review cannot assess critical numeric errors"
                )
            if self.occupied_strata_reviewed.status != "unassessed":
                raise ValueError("structure-only review cannot assess occupied strata")
            if self.expansion_gates_met:
                raise ValueError("unassessed source review cannot meet expansion gates")
        coverage = self.delivery_coverage
        universe = self.live_run.universe
        if (
            coverage.universe_total != universe.total
            or coverage.selected_for_run != universe.selected_for_run
            or coverage.completed != universe.completed
            or coverage.failed != universe.failed
            or coverage.missing_asset != universe.missing_asset
        ):
            raise ValueError("delivery coverage must follow the live-run denominator")
        return self


def record_source_review_report(
    *,
    live_run: CompanyProfileLiveRunReport,
    structural_checks: Sequence[StructuralCheck] = (),
    semantic_findings: Sequence[SemanticFinding] = (),
    fixture_guards: Sequence[FixtureGuardResult] = (),
    freshness: Sequence[FreshnessObservation] = (),
    tokens_used: int | None = None,
    elapsed_seconds: float | None = None,
    human_review_minutes: float | None = None,
) -> CompanyProfileSourceReviewReport:
    """Record independent source review without filling unassessed metrics as 0."""

    findings = tuple(semantic_findings)
    workload = SourceReviewWorkload(
        tokens_used=_count(tokens_used),
        elapsed_seconds=_duration(elapsed_seconds),
        human_review_minutes=_duration(human_review_minutes),
    )
    derived = _derived_metrics(
        live_run=live_run,
        findings=findings,
        workload=workload,
    )
    universe = live_run.universe
    return CompanyProfileSourceReviewReport(
        live_run=live_run,
        structural_checks=tuple(structural_checks),
        semantic_findings=findings,
        fixture_guards=tuple(fixture_guards),
        independently_reviewed_reports=derived["independently_reviewed_reports"],
        occupied_strata_reviewed=derived["occupied_strata_reviewed"],
        delivery_coverage=DeliveryCoverage(
            universe_total=universe.total,
            selected_for_run=universe.selected_for_run,
            completed=universe.completed,
            failed=universe.failed,
            missing_asset=universe.missing_asset,
            semantic_status="not_a_source_metric",
        ),
        source_recall=derived["source_recall"],
        source_accuracy=derived["source_accuracy"],
        critical_numeric_errors=derived["critical_numeric_errors"],
        freshness=tuple(freshness),
        workload=workload,
        expansion_gates_met=derived["expansion_gates_met"],
        scale_quality_claim_allowed=False,
        zero_recurrence_claimed=False,
    )


def persist_source_review_report(
    report: CompanyProfileSourceReviewReport,
    root: str | Path,
    *,
    destination: Path | None = None,
) -> Path:
    """Write company_profile_source_review.v1 next to the live-run report."""

    path = (
        Path(destination)
        if destination is not None
        else Path(root) / "reports" / f"{SOURCE_REVIEW_SCHEMA_VERSION}.json"
    )
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_suffix(".tmp")
    tmp.write_text(report.model_dump_json(indent=2), encoding="utf-8")
    tmp.replace(path)
    return path


def source_review_schema_manifest() -> dict[str, Any]:
    """Register the source-review schema without enabling production."""

    return {
        "schema_version": SOURCE_REVIEW_SCHEMA_VERSION,
        "production_authorization": PRODUCTION_AUTHORIZATION,
        "scale_quality_claim_allowed": False,
        "zero_recurrence_claimed": False,
        "unassessed_is_not_zero": True,
        "report_schema": CompanyProfileSourceReviewReport.model_json_schema(),
    }


def _derived_metrics(
    *,
    live_run: CompanyProfileLiveRunReport,
    findings: Sequence[SemanticFinding],
    workload: SourceReviewWorkload,
) -> dict[str, Any]:
    reviewed = {item.instrument_id for item in findings}
    recall = _source_recall(findings)
    accuracy = _source_accuracy(findings)
    critical = _critical_errors(findings)
    occupied = _occupied_strata(live_run, findings)
    return {
        "independently_reviewed_reports": len(reviewed),
        "occupied_strata_reviewed": occupied,
        "source_recall": recall,
        "source_accuracy": accuracy,
        "critical_numeric_errors": critical,
        "expansion_gates_met": _expansion_gates_met(
            live_run=live_run,
            findings=findings,
            reviewed=reviewed,
            occupied=occupied,
            recall=recall,
            accuracy=accuracy,
            critical=critical,
            workload=workload,
        ),
    }


def _occupied_strata(
    live_run: CompanyProfileLiveRunReport,
    findings: Sequence[SemanticFinding],
) -> AssessedCount | UnassessedValue:
    reviewed = {item.instrument_id for item in findings}
    if not reviewed or not live_run.selected_strata:
        return UnassessedValue()
    by_id = {
        item.instrument_id: (item.exchange, item.disclosure_form)
        for item in live_run.selected_strata
    }
    sampled = [instrument_id for instrument_id in reviewed if instrument_id in by_id]
    if not sampled:
        return UnassessedValue()
    return AssessedCount(value=len({by_id[instrument_id] for instrument_id in sampled}))


def _covers_required_aspects(findings: Sequence[SemanticFinding]) -> bool:
    reviewed: dict[str, set[str]] = {}
    for item in findings:
        reviewed.setdefault(item.instrument_id, set()).add(item.aspect)
    return bool(reviewed) and all(
        aspects >= _REQUIRED_ASPECTS for aspects in reviewed.values()
    )


def _expansion_gates_met(
    *,
    live_run: CompanyProfileLiveRunReport,
    findings: Sequence[SemanticFinding],
    reviewed: set[str],
    occupied: AssessedCount | UnassessedValue,
    recall: AssessedRatio | UnassessedValue,
    accuracy: AssessedRatio | UnassessedValue,
    critical: AssessedCount | UnassessedValue,
    workload: SourceReviewWorkload,
) -> bool:
    thresholds = live_run.plan.expansion_thresholds
    tokens = workload.tokens_used
    elapsed = workload.elapsed_seconds
    return (
        bool(findings)
        and _covers_required_aspects(findings)
        and len(reviewed) >= thresholds.min_independently_reviewed_reports
        and occupied.status == "assessed"
        and occupied.value >= thresholds.min_occupied_strata_reviewed
        and recall.status == "assessed"
        and recall.value >= thresholds.min_source_recall_ratio
        and accuracy.status == "assessed"
        and accuracy.value >= thresholds.min_source_accuracy_ratio
        and critical.status == "assessed"
        and critical.value <= thresholds.max_critical_numeric_errors
        and tokens.status == "assessed"
        and tokens.value <= thresholds.max_tokens
        and elapsed.status == "assessed"
        and elapsed.value <= thresholds.max_elapsed_seconds
    )


def _source_recall(
    findings: Sequence[SemanticFinding],
) -> AssessedRatio | UnassessedValue:
    disclosed = tuple(item for item in findings if item.disclosed_in_source)
    if not disclosed:
        return UnassessedValue()
    recalled = sum(item.present_in_delivery for item in disclosed)
    return AssessedRatio(
        numerator=recalled,
        denominator=len(disclosed),
        value=recalled / len(disclosed),
    )


def _source_accuracy(
    findings: Sequence[SemanticFinding],
) -> AssessedRatio | UnassessedValue:
    delivered = tuple(item for item in findings if item.present_in_delivery)
    if not delivered:
        return UnassessedValue()
    if any(item.fact_accurate is None for item in delivered):
        return UnassessedValue()
    accurate = sum(bool(item.fact_accurate) for item in delivered)
    return AssessedRatio(
        numerator=accurate,
        denominator=len(delivered),
        value=accurate / len(delivered),
    )


def _critical_errors(
    findings: Sequence[SemanticFinding],
) -> AssessedCount | UnassessedValue:
    if not findings:
        return UnassessedValue()
    return AssessedCount(
        value=sum(item.critical_numeric_error for item in findings)
    )


def _count(value: int | None) -> AssessedCount | UnassessedValue:
    if value is None:
        return UnassessedValue()
    return AssessedCount(value=int(value))


def _duration(value: float | None) -> AssessedDuration | UnassessedValue:
    if value is None:
        return UnassessedValue()
    return AssessedDuration(value=float(value))

